// frontend/src/hooks/useBreakpoint.js
// ============================================================
//  منبع واحد breakpointها برای کل پنل ادمین.
//
//  سه مفهوم مستقل:
//  - MOBILE_BP = 1024       → زیر این: drawer mode (سایدبار کشویی + هدر موبایل)
//  - TABLET_BP = 1536       → زیر این: سایدبار compact (w-16) بدون drawer
//                              (برای لپ‌تاپ‌های ۱۳ اینچ که w-72 خیلی جا می‌گیرد)
//  - NARROW_CONTENT_BP = 1280 → زیر این: صفحات محتوایی (کاربران، سفارشات و…)
//                              به‌جای جدول، کارت نشان می‌دهند
// ============================================================
import { useState, useEffect } from 'react';

export const MOBILE_BP = 1024;
export const TABLET_BP = 1536;
export const NARROW_CONTENT_BP = 1280;

function compute() {
  const width = typeof window !== 'undefined' ? window.innerWidth : 1920;
  return {
    width,
    isMobile: width < MOBILE_BP,                                       // drawer + هدر موبایل
    isTablet: width >= MOBILE_BP && width < TABLET_BP,                 // سایدبار compact
    isDesktop: width >= TABLET_BP,                                     // سایدبار کامل
    isNarrowContent: width < NARROW_CONTENT_BP,                        // کارت به‌جای جدول
  };
}

export function useBreakpoint() {
  const [bp, setBp] = useState(compute);

  useEffect(() => {
    const handler = () => setBp(compute());
    window.addEventListener('resize', handler);
    return () => window.removeEventListener('resize', handler);
  }, []);

  return bp;
}