// frontend/src/sheets/NutritionRequirements.jsx
// ✅ v2:
//  - حذف API_BASE محلی (http://localhost:8000)
//  - استفاده از publicAxios با baseURL (مسیر نسبی)
//  - بقیهٔ منطق و UI بدون تغییر

import React, { useState, useEffect, useMemo } from 'react';
import publicAxios from '../user/publicAxios';
import { toFa } from '../utils/numbers';
import { SiteImage } from '../utils/SiteImage';

// ============================================================
//  🛡️ Helper: استخراج پیام خطا از response
// ============================================================
const getErrorMsg = (err, fallback) => {
  const detail = err?.response?.data?.detail;
  if (typeof detail === 'string') return detail;
  if (err?.message && typeof err.message === 'string') return err.message;
  return fallback;
};

// ============================================================
//  هدر ستون‌ها
// ============================================================
const COLUMNS = [
  { key: 'nutrient_name', label: 'ماده مغذی', icon: '🧬', iconKey: 'icon_dna' },
  { key: 'symbol', label: 'نماد', icon: '🔤', mono: true },
  { key: 'unit', label: 'واحد', icon: '📏', iconKey: 'icon_ruler' },
  { key: 'adult_value', label: 'مقدار بالغ', icon: '🎯', iconKey: 'icon_target', number: true },
  { key: 'min_value', label: 'حداقل', icon: '⬇️', iconKey: 'icon_download', number: true, min: true },
  { key: 'max_value', label: 'حداکثر', icon: '⬆️', number: true, max: true },
  { key: 'role', label: 'نقش', icon: '💡', iconKey: 'icon_lightbulb', wide: true },
  { key: 'sources', label: 'منابع', icon: '🍗', iconKey: 'allergen_chicken', wide: true },
  { key: 'calc_type', label: 'نوع محاسبه', icon: '⚙️', iconKey: 'icon_settings' },
];

// ============================================================
//  فرمت اعداد
// ============================================================
const fmtNum = (n) => {
  if (n === null || n === undefined || n === '') return '—';
  const num = Number(n);
  if (Number.isNaN(num)) return n;
  return toFa(num);
};

// ============================================================
//  🎨 رنگ‌بندی دسته‌ها — Editorial palette
// ============================================================
const CATEGORY_COLORS = [
  {
    gradient: 'from-brand-500 to-brand-700',
    chip: 'bg-brand-50 dark:bg-brand-500/15 border-brand-200 dark:border-brand-500/30 text-brand-700 dark:text-brand-300 hover:bg-brand-100 dark:hover:bg-brand-500/25',
    badge:
      'bg-brand-100 dark:bg-brand-500/20 text-brand-800 dark:text-brand-200 border-brand-200 dark:border-brand-500/30',
    icon: '🧪', iconKey: 'icon_flask',
  },
  {
    gradient: 'from-accent-500 to-accent-700',
    chip: 'bg-accent-50 dark:bg-accent-500/15 border-accent-200 dark:border-accent-500/30 text-accent-700 dark:text-accent-300 hover:bg-accent-100 dark:hover:bg-accent-500/25',
    badge:
      'bg-accent-100 dark:bg-accent-500/20 text-accent-800 dark:text-accent-200 border-accent-200 dark:border-accent-500/30',
    icon: '🌿', iconKey: 'icon_leaf',
  },
  {
    gradient: 'from-rose-500 to-rose-700',
    chip: 'bg-rose-50 dark:bg-rose-500/15 border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 hover:bg-rose-100 dark:hover:bg-rose-500/25',
    badge:
      'bg-rose-100 dark:bg-rose-500/20 text-rose-800 dark:text-rose-200 border-rose-200 dark:border-rose-500/30',
    icon: '⚗️', iconKey: 'icon_flask',
  },
  {
    gradient: 'from-ink-600 to-ink-800',
    chip: 'bg-ink-100 dark:bg-ink-700 border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 hover:bg-ink-200 dark:hover:bg-ink-600',
    badge:
      'bg-ink-200 dark:bg-ink-700 text-ink-800 dark:text-cream-100 border-ink-300 dark:border-dark-600',
    icon: '🔬', iconKey: 'icon_dna',
  },
  {
    gradient: 'from-brand-600 to-brand-800',
    chip: 'bg-brand-100 dark:bg-brand-500/20 border-brand-300 dark:border-brand-500/40 text-brand-800 dark:text-brand-200 hover:bg-brand-200 dark:hover:bg-brand-500/30',
    badge:
      'bg-brand-200 dark:bg-brand-500/30 text-brand-900 dark:text-brand-100 border-brand-300 dark:border-brand-500/40',
    icon: '❤️', iconKey: 'icon_heart',
  },
  {
    gradient: 'from-accent-600 to-accent-800',
    chip: 'bg-accent-100 dark:bg-accent-500/20 border-accent-300 dark:border-accent-500/40 text-accent-800 dark:text-accent-200 hover:bg-accent-200 dark:hover:bg-accent-500/30',
    badge:
      'bg-accent-200 dark:bg-accent-500/30 text-accent-900 dark:text-accent-100 border-accent-300 dark:border-accent-500/40',
    icon: '💧', iconKey: 'icon_drop',
  },
];

const getCategoryStyle = (idx) => CATEGORY_COLORS[idx % CATEGORY_COLORS.length];

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function NutritionRequirements() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeCategory, setActiveCategory] = useState('all');

  const [openCategories, setOpenCategories] = useState({});

  // ============================================================
  //  دریافت داده — مسیر نسبی با baseURL
  // ============================================================
  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError(null);

    publicAxios
      .get('/api/nutrition-standards')
      .then((res) => {
        if (!mounted) return;
        setData(res.data || []);
      })
      .catch((err) => {
        if (!mounted) return;
        setError(getErrorMsg(err, 'خطای نامشخص در دریافت اطلاعات'));
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });

    return () => {
      mounted = false;
    };
  }, []);

  // ============================================================
  //  Debounce
  // ============================================================
  useEffect(() => {
    const t = setTimeout(() => setSearchTerm(searchInput), 300);
    return () => clearTimeout(t);
  }, [searchInput]);

  // ============================================================
  //  دسته‌های یکتا
  // ============================================================
  const categories = useMemo(() => {
    const set = new Set();
    data.forEach((r) => {
      if (r.category) set.add(r.category);
    });
    return Array.from(set);
  }, [data]);

  // ============================================================
  //  گروه‌بندی
  // ============================================================
  const grouped = useMemo(() => {
    const q = searchTerm.trim().toLowerCase();
    const acc = {};

    data.forEach((row) => {
      if (activeCategory !== 'all' && row.category !== activeCategory) return;

      if (q) {
        const hay = [
          row.nutrient_name,
          row.symbol,
          row.category,
          row.role,
          row.sources,
        ]
          .filter(Boolean)
          .join(' ')
          .toLowerCase();
        if (!hay.includes(q)) return;
      }

      const cat = row.category || 'سایر';
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(row);
    });

    return acc;
  }, [data, searchTerm, activeCategory]);

  const categoryKeys = Object.keys(grouped);
  const totalRows = useMemo(
    () => Object.values(grouped).reduce((sum, arr) => sum + arr.length, 0),
    [grouped]
  );

  // ============================================================
  //  باز کردن همه دسته‌ها در بار اول
  // ============================================================
  useEffect(() => {
    if (categoryKeys.length > 0 && Object.keys(openCategories).length === 0) {
      const allOpen = {};
      categoryKeys.forEach((c) => {
        allOpen[c] = true;
      });
      setOpenCategories(allOpen);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [categoryKeys.length]);

  // ============================================================
  //  وقتی سرچ فعاله همه باز بشن
  // ============================================================
  useEffect(() => {
    if (searchTerm.trim()) {
      const allOpen = {};
      categoryKeys.forEach((c) => {
        allOpen[c] = true;
      });
      setOpenCategories(allOpen);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchTerm]);

  const toggleCategory = (cat) => {
    setOpenCategories((prev) => ({ ...prev, [cat]: !prev[cat] }));
  };

  const toggleAll = () => {
    const allOpen = categoryKeys.every((c) => openCategories[c]);
    const next = {};
    categoryKeys.forEach((c) => {
      next[c] = !allOpen;
    });
    setOpenCategories(next);
  };

  const clearFilters = () => {
    setSearchInput('');
    setActiveCategory('all');
  };

  const hasFilter = Boolean(searchInput.trim() || activeCategory !== 'all');

  // ============================================================
  //  Stats
  // ============================================================
  const stats = useMemo(() => {
    const totalAll = data.length;
    const categoriesCount = categories.length;
    const calcTypes = new Set();
    data.forEach((r) => {
      if (r.calc_type) calcTypes.add(r.calc_type);
    });
    return { totalAll, categoriesCount, calcTypes: calcTypes.size };
  }, [data, categories]);

  // ============================================================
  //  رندر
  // ============================================================
  return (
    <div className="space-y-5" dir="rtl">
      {/* ============================================================ */}
      {/*  Hero Editorial Card                                          */}
      {/* ============================================================ */}
      <div className="relative bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden noise-overlay">
        <div
          className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-brand-500"
          aria-hidden="true"
        />

        <div className="p-6 sm:p-7">
          <div className="flex items-center gap-3 mb-5">
            <div className="w-10 h-px bg-brand-500" aria-hidden="true" />
            <span className="text-[10px] sm:text-[11px] font-black text-brand-600 dark:text-brand-400">
              مرجع علمی
            </span>
          </div>

          <div className="flex items-start gap-4 mb-6">
            <div
              className="w-14 h-14 sm:w-16 sm:h-16 rounded-3xl bg-brand-gradient flex items-center justify-center text-2xl sm:text-3xl flex-shrink-0 shadow-brand"
              aria-hidden="true"
            >
              📊
            </div>
            <div className="min-w-0 flex-1">
              <h2 className="font-display font-black text-2xl sm:text-3xl md:text-4xl text-ink-900 dark:text-cream-100 leading-tight tracking-tightest mb-2">
                استانداردهای تغذیه‌ای مرجع
              </h2>
              <p className="text-xs sm:text-sm text-ink-500 dark:text-cream-400 leading-relaxed">
                مقادیر مرجع نیازهای تغذیه‌ای سگ بر اساس استانداردهای NRC و
                AAFCO
              </p>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2.5">
            <div className="bg-paper-100 dark:bg-ink-900/50 rounded-2xl px-3 py-3 text-center border border-ink-200 dark:border-dark-700">
              <div className="text-[10px] text-ink-500 dark:text-cream-400 mb-1 flex items-center justify-center gap-1 font-black">
                <SiteImage imageKey="icon_dna" fallback="🧬" alt="" className="leading-none inline-flex" />
                <span>مواد مغذی</span>
              </div>
              <div className="font-display font-black text-base sm:text-lg text-brand-600 dark:text-brand-400 font-num tabular-nums">
                {toFa(stats.totalAll)}
              </div>
            </div>
            <div className="bg-paper-100 dark:bg-ink-900/50 rounded-2xl px-3 py-3 text-center border border-ink-200 dark:border-dark-700">
              <div className="text-[10px] text-ink-500 dark:text-cream-400 mb-1 flex items-center justify-center gap-1 font-black">
                <SiteImage imageKey="icon_folder" fallback="📂" alt="" className="leading-none inline-flex" />
                <span>دسته‌ها</span>
              </div>
              <div className="font-display font-black text-base sm:text-lg text-accent-600 dark:text-accent-400 font-num tabular-nums">
                {toFa(stats.categoriesCount)}
              </div>
            </div>
            <div className="bg-paper-100 dark:bg-ink-900/50 rounded-2xl px-3 py-3 text-center border border-ink-200 dark:border-dark-700">
              <div className="text-[10px] text-ink-500 dark:text-cream-400 mb-1 flex items-center justify-center gap-1 font-black">
                <span aria-hidden="true">⚙️</span>
                <span>انواع محاسبه</span>
              </div>
              <div className="font-display font-black text-base sm:text-lg text-ink-800 dark:text-cream-100 font-num tabular-nums">
                {toFa(stats.calcTypes)}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  Info Note — Editorial brand                                  */}
      {/* ============================================================ */}
      <div className="bg-brand-50 dark:bg-brand-500/15 border border-brand-200 dark:border-brand-500/30 rounded-3xl p-4 flex items-start gap-3">
        <div
          className="w-10 h-10 rounded-2xl bg-brand-100 dark:bg-brand-500/20 flex items-center justify-center text-lg flex-shrink-0 text-brand-700 dark:text-brand-300"
          aria-hidden="true"
        >
          💡
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-display font-black text-brand-900 dark:text-brand-200 text-xs mb-1">
            توجه
          </div>
          <div className="text-[11px] text-brand-800 dark:text-brand-300 leading-relaxed font-bold">
            این جدول صرفاً جهت مطالعه و مرجع علمی است — قابل ویرایش نیست.
          </div>
        </div>
      </div>

      {/* ============================================================ */}
      {/*  Search + Filter                                              */}
      {/* ============================================================ */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-4 sm:p-5 shadow-soft space-y-4">
        <div className="relative">
          <input
            type="text"
            value={searchInput}
            onChange={(e) => setSearchInput(e.target.value)}
            placeholder="🔍 جستجو در ماده مغذی، نماد، دسته..."
            className="w-full px-4 py-3 min-h-[48px] pr-11 pl-11 border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition"
          />
          <SiteImage imageKey="icon_search" fallback="🔍" alt="" className="absolute right-3.5 top-1/2 -translate-y-1/2 text-ink-400 dark:text-cream-500 pointer-events-none" />
          {searchInput && (
            <button
              type="button"
              onClick={() => setSearchInput('')}
              className="absolute left-2 top-1/2 -translate-y-1/2 w-9 h-9 flex items-center justify-center text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 rounded-xl transition touch-target"
              title="پاک کردن"
              aria-label="پاک کردن جستجو"
            >
              ✕
            </button>
          )}
        </div>

        {/* Category chips */}
        <div className="pt-4 border-t border-ink-200 dark:border-dark-700">
          <div className="overflow-x-auto scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
            <div className="flex items-center gap-2 min-w-max sm:min-w-0 sm:flex-wrap">
              <button
                type="button"
                onClick={() => setActiveCategory('all')}
                className={`min-h-[40px] px-3.5 py-2 rounded-xl border text-xs font-black transition flex items-center gap-1.5 flex-shrink-0 touch-target active:scale-[0.98] ${
                  activeCategory === 'all'
                    ? 'bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 border-ink-900 dark:border-cream-100 shadow-soft'
                    : 'bg-paper-100 dark:bg-ink-700/50 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600 hover:bg-paper-200 dark:hover:bg-ink-700 active:bg-paper-300'
                }`}
              >
                <SiteImage imageKey="icon_clipboard" fallback="📋" alt="" className="leading-none inline-flex" />
                <span>همه</span>
                <span
                  className={`text-[10px] px-1.5 py-0.5 rounded-full font-num font-black tabular-nums ${
                    activeCategory === 'all'
                      ? 'bg-cream-50/20 dark:bg-ink-900/15'
                      : 'bg-paper-50 dark:bg-ink-800'
                  }`}
                >
                  {toFa(stats.totalAll)}
                </span>
              </button>

              {categories.map((cat, idx) => {
                const isActive = activeCategory === cat;
                const style = getCategoryStyle(idx);
                const count = data.filter((r) => r.category === cat).length;
                return (
                  <button
                    type="button"
                    key={cat}
                    onClick={() => setActiveCategory(isActive ? 'all' : cat)}
                    className={`min-h-[40px] px-3.5 py-2 rounded-xl border text-xs font-black transition flex items-center gap-1.5 flex-shrink-0 touch-target active:scale-[0.98] ${
                      isActive
                        ? 'bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 border-ink-900 dark:border-cream-100 shadow-soft'
                        : style.chip
                    }`}
                  >
                    <span aria-hidden="true">{style.icon}</span>
                    <span>{cat}</span>
                    <span
                      className={`text-[10px] px-1.5 py-0.5 rounded-full font-num font-black tabular-nums ${
                        isActive
                          ? 'bg-cream-50/20 dark:bg-ink-900/15'
                          : 'bg-paper-50 dark:bg-ink-800'
                      }`}
                    >
                      {toFa(count)}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          {categoryKeys.length > 1 && (
            <div className="mt-3 flex justify-end">
              <button
                type="button"
                onClick={toggleAll}
                className="w-full sm:w-auto min-h-[44px] px-4 py-2.5 bg-paper-100 dark:bg-ink-700/50 border border-ink-200 dark:border-dark-600 rounded-2xl text-[11px] font-black text-ink-700 dark:text-cream-200 hover:bg-paper-200 dark:hover:bg-ink-700 active:bg-paper-300 transition flex items-center justify-center gap-2 touch-target"
              >
                {categoryKeys.every((c) => openCategories[c]) ? (
                  <>
                    <SiteImage imageKey="icon_arrow_up" fallback="🔼" alt="" className="leading-none inline-flex" />
                    <span>بستن همه</span>
                  </>
                ) : (
                  <>
                    <SiteImage imageKey="icon_arrow_down" fallback="🔽" alt="" className="leading-none inline-flex" />
                    <span>باز کردن همه</span>
                  </>
                )}
              </button>
            </div>
          )}
        </div>

        {hasFilter && (
          <div className="flex flex-wrap items-center justify-between gap-2 pt-4 border-t border-ink-200 dark:border-dark-700">
            <div className="text-[11px] text-ink-500 dark:text-cream-400 break-safe font-bold">
              نمایش{' '}
              <span className="font-black text-ink-800 dark:text-cream-100 font-num tabular-nums">
                {toFa(totalRows)}
              </span>{' '}
              از{' '}
              <span className="font-num tabular-nums">
                {toFa(stats.totalAll)}
              </span>{' '}
              ماده
              {searchTerm && (
                <span className="mr-2 text-ink-400 dark:text-cream-500">
                  «{searchTerm}»
                </span>
              )}
            </div>
            <button
              type="button"
              onClick={clearFilters}
              className="min-h-[40px] px-3.5 py-1.5 bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 active:bg-rose-200 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 rounded-xl text-[11px] font-black transition flex items-center gap-1 touch-target"
            >
              <SiteImage imageKey="icon_close" fallback="✕" alt="" className="leading-none inline-flex" />
              <span>پاک کردن</span>
            </button>
          </div>
        )}
      </div>

      {/* ============================================================ */}
      {/*  Loading                                                     */}
      {/* ============================================================ */}
      {loading && (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft p-10 sm:p-14 text-center">
          <div className="inline-block w-10 h-10 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-3" />
          <div className="text-ink-500 dark:text-cream-400 text-sm font-black">
            در حال بارگذاری استانداردها...
          </div>
        </div>
      )}

      {/* ============================================================ */}
      {/*  Error                                                       */}
      {/* ============================================================ */}
      {!loading && error && (
        <div className="bg-rose-50 dark:bg-rose-500/15 border-2 border-rose-200 dark:border-rose-500/30 rounded-3xl p-5 sm:p-7 text-center">
          <div className="text-5xl mb-3 opacity-70" aria-hidden="true">
            ⚠️
          </div>
          <div className="font-display font-black text-rose-800 dark:text-rose-200 mb-2 text-sm">
            خطا در دریافت داده
          </div>
          <div className="text-xs text-rose-600 dark:text-rose-300 mb-5 break-safe leading-relaxed font-bold">
            {error}
          </div>
          <button
            type="button"
            onClick={() => window.location.reload()}
            className="w-full sm:w-auto min-h-[48px] px-5 py-3 bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white rounded-2xl text-xs font-black transition shadow-soft touch-target"
          >
            🔄 تلاش مجدد
          </button>
        </div>
      )}

      {/* ============================================================ */}
      {/*  Empty                                                       */}
      {/* ============================================================ */}
      {!loading && !error && totalRows === 0 && (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft p-10 sm:p-14 text-center">
          <div className="text-5xl mb-4 opacity-50" aria-hidden="true">
            📭
          </div>
          <div className="font-display font-black text-ink-800 dark:text-cream-100 mb-2 text-base">
            {searchTerm
              ? 'نتیجه‌ای با این جستجو یافت نشد'
              : 'هیچ داده‌ای ثبت نشده است'}
          </div>
          {hasFilter && (
            <button
              type="button"
              onClick={clearFilters}
              className="mt-5 w-full sm:w-auto min-h-[48px] inline-flex items-center justify-center gap-2 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white px-5 py-3 rounded-2xl text-xs font-black transition shadow-brand touch-target"
            >
              <SiteImage imageKey="icon_close" fallback="✕" alt="" className="leading-none inline-flex" />
              <span>پاک کردن فیلترها</span>
            </button>
          )}
        </div>
      )}

      {/* ============================================================ */}
      {/*  Categories                                                  */}
      {/* ============================================================ */}
      {!loading && !error && totalRows > 0 && (
        <div className="space-y-4">
          {categoryKeys.map((cat, catIdx) => {
            const items = grouped[cat];
            const isOpen = openCategories[cat] === true;
            const originalIdx = categories.indexOf(cat);
            const style = getCategoryStyle(
              originalIdx >= 0 ? originalIdx : catIdx
            );

            return (
              <div
                key={cat}
                className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden"
              >
                <button
                  type="button"
                  onClick={() => toggleCategory(cat)}
                  className="w-full flex items-center justify-between gap-3 p-4 sm:p-5 min-h-[76px] hover:bg-paper-100/60 dark:hover:bg-ink-700/40 active:bg-paper-100 dark:active:bg-ink-700/60 transition text-right touch-target"
                  aria-expanded={isOpen}
                >
                  <div className="flex items-center gap-3 min-w-0 flex-1">
                    <div
                      className={`w-11 h-11 sm:w-12 sm:h-12 rounded-2xl bg-gradient-to-br ${style.gradient} flex items-center justify-center text-white text-lg sm:text-xl flex-shrink-0 shadow-soft`}
                      aria-hidden="true"
                    >
                      {style.icon}
                    </div>
                    <div className="text-right min-w-0">
                      <div className="font-display font-black text-ink-900 dark:text-cream-100 text-sm flex items-center gap-2 flex-wrap">
                        <span className="truncate">{cat}</span>
                        <span
                          className={`text-[10px] px-2 py-0.5 rounded-full border font-black whitespace-nowrap font-num tabular-nums ${style.badge}`}
                        >
                          {toFa(items.length)} ماده
                        </span>
                      </div>
                      <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-0.5 leading-relaxed">
                        مواد مغذی این دسته
                      </div>
                    </div>
                  </div>
                  <SiteImage imageKey="icon_chevron_left" fallback="◀" alt="" className="leading-none inline-flex" />
                </button>

                {isOpen && (
                  <div className="border-t border-ink-200 dark:border-dark-700 overflow-x-auto scrollbar-hide animate-expand-down">
                    <div className="min-w-max sm:min-w-0">
                      <table className="w-full text-sm min-w-[900px] sm:min-w-0">
                        <thead className="bg-ink-900 dark:bg-ink-950 text-cream-100">
                          <tr>
                            <th className="p-3 text-center font-black text-[11px] whitespace-nowrap w-14">
                              #
                            </th>
                            {COLUMNS.map((col) => (
                              <th
                                key={col.key}
                                className={`p-3 font-black text-[11px] whitespace-nowrap ${
                                  col.wide ? 'text-right' : 'text-center'
                                }`}
                              >
                                <div
                                  className={`flex items-center gap-1 ${
                                    col.wide ? '' : 'justify-center'
                                  }`}
                                >
                                  <span aria-hidden="true">{col.icon}</span>
                                  <span>{col.label}</span>
                                </div>
                              </th>
                            ))}
                          </tr>
                        </thead>

                        <tbody className="divide-y divide-ink-200 dark:divide-dark-700">
                          {items.map((row, idx) => (
                            <tr
                              key={idx}
                              className="hover:bg-paper-100/60 dark:hover:bg-ink-700/40 active:bg-paper-100 dark:active:bg-ink-700/60 transition"
                            >
                              <td className="p-3 text-center">
                                <span className="inline-flex items-center justify-center w-7 h-7 rounded-2xl bg-paper-100 dark:bg-ink-700 text-ink-500 dark:text-cream-400 text-[10px] font-black font-num tabular-nums">
                                  {toFa(idx + 1)}
                                </span>
                              </td>

                              {COLUMNS.map((col) => {
                                const value = row[col.key];
                                const isNumber = col.number;

                                return (
                                  <td
                                    key={col.key}
                                    className={`p-3 text-xs ${
                                      col.mono ? 'font-mono' : ''
                                    } ${
                                      col.wide
                                        ? 'max-w-xs'
                                        : 'whitespace-nowrap text-center'
                                    }`}
                                    dir={col.mono ? 'ltr' : 'rtl'}
                                  >
                                    {isNumber ? (
                                      <span
                                        className={`inline-block px-2.5 py-1 rounded-2xl font-black font-num tabular-nums ${
                                          col.min
                                            ? 'bg-rose-50 dark:bg-rose-500/15 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-500/30'
                                            : col.max
                                            ? 'bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border border-accent-200 dark:border-accent-500/30'
                                            : 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300 border border-brand-200 dark:border-brand-500/30'
                                        }`}
                                      >
                                        {fmtNum(value)}
                                      </span>
                                    ) : (
                                      <span
                                        className={`${
                                          col.wide
                                            ? 'leading-relaxed text-ink-600 dark:text-cream-300 font-bold'
                                            : 'text-ink-800 dark:text-cream-100 font-black'
                                        }`}
                                      >
                                        {value || '—'}
                                      </span>
                                    )}
                                  </td>
                                );
                              })}
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* ============================================================ */}
      {/*  Footer Info                                                 */}
      {/* ============================================================ */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-4 flex items-start gap-3 shadow-soft">
        <div
          className="w-10 h-10 rounded-2xl bg-accent-100 dark:bg-accent-500/20 flex items-center justify-center text-lg flex-shrink-0 text-accent-700 dark:text-accent-300"
          aria-hidden="true"
        >
          📚
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-display font-black text-ink-900 dark:text-cream-100 text-xs mb-1.5">
            مراجع علمی
          </div>
          <div className="text-[11px] text-ink-600 dark:text-cream-300 leading-relaxed break-safe font-mono font-bold">
            NRC 2006 · AAFCO 2024 · FEDIAF 2024 · WSAVA 2024
          </div>
        </div>
      </div>
    </div>
  );
}