// frontend/src/App.js
// ✅ v3: اصلاح ScrollToTop برای پشتیبانی کامل از hash
//  - پیمایش به `/#order-form-section` از پنل کاربر حالا درست کار می‌کند
//  - اسکرول با offset هدر ثابت (۹۶px)
//  - retry اگر المان هنوز mount نشده باشد
//  - پشتیبانی از کلیک مجدد روی همان hash (location.key)
//  - cart و سایر روت‌ها دست‌نخورده
// ============================================================

import React, { useState, useEffect } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate,
  useLocation,
} from 'react-router-dom';

import UserApp from './user/UserApp';
import AdminApp from './admin/AdminApp';
import AdminLogin from './admin/AdminLogin';
import UserLogin from './user/UserLogin';
import UserRegister from './user/UserRegister';
import UserPanel from './user/UserPanel';
import Cart from './user/pages/Cart';
import NotFound from './user/pages/NotFound';

// ============================================================
//  🎯 ScrollToTop — اسکرول به بالا یا به المان hash
//  - بدون hash → اسکرول به بالا
//  - با hash → اسکرول به المان با offset هدر ثابت
//  - retry برای زمانی که المان هنوز mount نشده
//  - location.key برای پشتیبانی از کلیک مجدد روی همان hash
// ============================================================
const HEADER_OFFSET = 96; // ارتفاع هدر ثابت کاربر
const MAX_SCROLL_ATTEMPTS = 20; // ~۱ ثانیه با فاصله ۵۰ms
const SCROLL_RETRY_DELAY = 50;

function ScrollToTop() {
  const location = useLocation();
  const { pathname, hash, key } = location;

  useEffect(() => {
    // ─── بدون hash → اسکرول به بالا ───
    if (!hash) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    // ─── با hash → پیدا کردن المان و اسکرول ───
    const id = hash.replace(/^#/, '');
    if (!id) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    let cancelled = false;
    let attempts = 0;
    let timer = null;

    const tryScroll = () => {
      if (cancelled) return;

      const el = document.getElementById(id);
      if (el) {
        const top =
          el.getBoundingClientRect().top +
          window.pageYOffset -
          HEADER_OFFSET;
        window.scrollTo({
          top: Math.max(0, top),
          behavior: 'smooth',
        });
        return;
      }

      attempts += 1;
      if (attempts < MAX_SCROLL_ATTEMPTS) {
        timer = setTimeout(tryScroll, SCROLL_RETRY_DELAY);
      }
    };

    // صبر کن React اول DOM رو commit کنه، بعد scroll بزنیم
    const raf = requestAnimationFrame(tryScroll);

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      if (timer) clearTimeout(timer);
    };
    // key → برای اینکه کلیک مجدد روی همون hash هم effect رو trigger کنه
  }, [pathname, hash, key]);

  return null;
}

// ============================================================
//  🔒 ProtectedRoute — فقط کاربران لاگین‌کرده
// ============================================================
function ProtectedRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));

  if (!isLoggedIn) {
    return <Navigate to="/login?next=panel" replace />;
  }

  return children;
}

// ============================================================
//  🔒 AdminRoute — فقط ادمین‌های لاگین‌کرده
// ============================================================
function AdminRoute({ children }) {
  const [isAdmin, setIsAdmin] = useState(
    () => !!localStorage.getItem('adminToken')
  );

  useEffect(() => {
    const handler = () => setIsAdmin(!!localStorage.getItem('adminToken'));
    window.addEventListener('storage', handler);
    window.addEventListener('adminAuthUpdated', handler);
    return () => {
      window.removeEventListener('storage', handler);
      window.removeEventListener('adminAuthUpdated', handler);
    };
  }, []);

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }

  return children;
}

// ============================================================
//  🔓 PublicOnlyRoute — فقط کاربران مهمان (نه لاگین‌کرده)
// ============================================================
function PublicOnlyRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));

  if (isLoggedIn) {
    return <Navigate to="/panel" replace />;
  }

  return children;
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
function AppContent() {
  return (
    <>
      <ScrollToTop />
      <Routes>
        {/* ===== روت‌های عمومی ===== */}
        <Route path="/" element={<UserApp />} />

        {/* 🛒 سبد خرید — عمومی (برای مهمان و کاربر لاگین) */}
        <Route path="/cart" element={<Cart />} />

        {/* ===== روت‌های احراز هویت کاربر ===== */}
        <Route
          path="/login"
          element={
            <PublicOnlyRoute>
              <UserLogin />
            </PublicOnlyRoute>
          }
        />
        <Route
          path="/register"
          element={
            <PublicOnlyRoute>
              <UserRegister />
            </PublicOnlyRoute>
          }
        />

        {/* ===== پنل کاربر (نیاز به لاگین) ===== */}
        <Route
          path="/panel/*"
          element={
            <ProtectedRoute>
              <UserPanel />
            </ProtectedRoute>
          }
        />

        {/* ===== پنل ادمین ===== */}
        <Route path="/admin/login" element={<AdminLogin />} />
        <Route
          path="/admin/*"
          element={
            <AdminRoute>
              <AdminApp />
            </AdminRoute>
          }
        />

        {/* ===== 404 ===== */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </>
  );
}

// ============================================================
//  Root App — BrowserRouter
// ============================================================
export default function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}