  CATEGORY_MAP[cat] || {
    gradient: 'bg-ink-500',
    icon: '📦', iconKey: 'icon_orders',
    label: cat || 'نامشخص',
    rowBg: 'bg-ink-100/50 dark:bg-ink-700/30',
    badge:
      'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600',
    chip:
      'bg-ink-100 dark:bg-ink-700 border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200',
    strip: 'bg-ink-500',
  };

// ============================================================
//  Helpers
// ============================================================
const fmt = (n) => Math.round(n || 0).toLocaleString('fa-IR');
const fmtPrice = fmt;

const fmtKg = (grams) => {
  const kg = (Number(grams) || 0) / 1000;
  return kg.toLocaleString('fa-IR', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  });
};

const getStorageKey = (orderId) => `prepListChecked_${orderId}`;

// ============================================================
//  Sort Icon — Editorial
// ============================================================
const SortIcon = ({ columnKey, sortConfig }) => {
  if (sortConfig.key !== columnKey) {
    return (
      <SiteImage imageKey="icon_sort" fallback="↕" alt="" className="text-cream-100/40 text-xs" />
    );
  }
  return sortConfig.direction === 'ascending' ? (
    <SiteImage imageKey="icon_sort_up" fallback="▲" alt="" className="text-cream-50 text-xs" />
  ) : (
    <SiteImage imageKey="icon_sort_down" fallback="▼" alt="" className="text-cream-50 text-xs" />
  );
};

// ============================================================
