// ✅ v1.1: علامت تیک هاردکد (✓) با SiteImage icon_check جایگزین شد
//         (با فیلتر CSS برای حفظ رنگ سفید در حالت انتخاب‌شده)
import React, { useMemo } from 'react';
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  📋 دسته‌بندی آلرژی‌ها
// ============================================================
export const ALLERGEN_CATEGORIES = [
  {
    key: 'chicken',
    name: 'مرغ و ماکیان',
    description: 'مرغ، سنگدان، پای مرغ',
    allergens: [{ value: 'chicken', label: 'مرغ' }],
  },
  {
    key: 'beef',
    name: 'گوشت گاو',
    description: 'گوشت گاو و مشتقات',
    allergens: [{ value: 'beef', label: 'گوشت گاو' }],
  },
  {
    key: 'wheat',
    name: 'گندم و گلوتن',
    description: 'گندم، ماکارونی، نان',
    allergens: [{ value: 'wheat', label: 'گندم' }],
  },
];

// ============================================================
//  🎨 پالت رنگ — یک رنگ متمایز برای هر دسته
// ============================================================
const CATEGORY_STYLES = {
  chicken: {
    icon: '🍗',
    iconKey: 'allergen_chicken',
    idle: 'bg-paper-50 dark:bg-ink-800/60 border-ink-200/70 dark:border-dark-700/60 hover:border-rose-300 dark:hover:border-rose-500/40 hover:bg-rose-50/30 dark:hover:bg-rose-500/5',
    active: 'bg-rose-50/70 dark:bg-rose-500/12 border-rose-300 dark:border-rose-500/50',
    iconIdle: 'bg-rose-50 dark:bg-rose-500/10 text-rose-600 dark:text-rose-400',
    iconActive: 'bg-rose-500 text-white shadow-soft',
    textActive: 'text-rose-800 dark:text-rose-200',
    subActive: 'text-rose-600 dark:text-rose-400',
    checkActive: 'bg-rose-500 border-rose-500 text-white',
    checkIdle: 'border-ink-300 dark:border-dark-500',
  },
  beef: {
    icon: '🥩',
    iconKey: 'allergen_beef',
    idle: 'bg-paper-50 dark:bg-ink-800/60 border-ink-200/70 dark:border-dark-700/60 hover:border-brand-300 dark:hover:border-brand-500/40 hover:bg-brand-50/30 dark:hover:bg-brand-500/5',
    active: 'bg-brand-50/70 dark:bg-brand-500/12 border-brand-300 dark:border-brand-500/50',
    iconIdle: 'bg-brand-50 dark:bg-brand-500/10 text-brand-600 dark:text-brand-400',
    iconActive: 'bg-brand-gradient text-white shadow-brand',
    textActive: 'text-brand-800 dark:text-brand-200',
    subActive: 'text-brand-600 dark:text-brand-400',
    checkActive: 'bg-brand-500 border-brand-500 text-white',
    checkIdle: 'border-ink-300 dark:border-dark-500',
  },
  wheat: {
    icon: '🌾',
    iconKey: 'allergen_wheat',
    idle: 'bg-paper-50 dark:bg-ink-800/60 border-ink-200/70 dark:border-dark-700/60 hover:border-accent-300 dark:hover:border-accent-500/40 hover:bg-accent-50/30 dark:hover:bg-accent-500/5',
    active: 'bg-accent-50/70 dark:bg-accent-500/12 border-accent-300 dark:border-accent-500/50',
    iconIdle: 'bg-accent-50 dark:bg-accent-500/10 text-accent-600 dark:text-accent-400',
    iconActive: 'bg-accent-500 text-white shadow-soft',
    textActive: 'text-accent-800 dark:text-accent-200',
    subActive: 'text-accent-600 dark:text-accent-400',
    checkActive: 'bg-accent-500 border-accent-500 text-white',
    checkIdle: 'border-ink-300 dark:border-dark-500',
  },
};

// ============================================================
//  🔧 Helpers
// ============================================================
const normalizeTag = (tag) =>
  String(tag || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/-/g, '_');

const arraysEqual = (a, b) => {
  if (a.length !== b.length) return false;
  const first = [...a].sort();
  const second = [...b].sort();
  return first.every((item, index) => item === second[index]);
};

// ============================================================
//  🎯 کامپوننت اصلی
// ============================================================
export default function AllergenSelector({
  value = [],
  onChange,
  disabled = false,
}) {
  const selectedSet = useMemo(
    () =>
      new Set(
        (Array.isArray(value) ? value : [])
          .map(normalizeTag)
          .filter(Boolean)
      ),
    [value]
  );

  const toggleAllergen = (allergenValue) => {
    if (disabled) return;

    const normalized = normalizeTag(allergenValue);
    const next = new Set(selectedSet);

    if (next.has(normalized)) next.delete(normalized);
    else next.add(normalized);

    const nextArray = [...next];
    if (arraysEqual([...selectedSet], nextArray)) return;

    onChange?.(nextArray);
  };

  return (
    <div className="space-y-2" dir="rtl">
      {ALLERGEN_CATEGORIES.map((category) => {
        const style = CATEGORY_STYLES[category.key];
        const allergen = category.allergens[0];
        const isSelected = selectedSet.has(normalizeTag(allergen.value));

        return (
          <button
            key={category.key}
            type="button"
            onClick={() => toggleAllergen(allergen.value)}
            disabled={disabled}
            aria-pressed={isSelected}
            aria-label={
              isSelected
                ? `حذف ${category.name} از آلرژی‌ها`
                : `افزودن ${category.name} به آلرژی‌ها`
            }
            className={`group w-full flex items-center gap-3 p-3 rounded-2xl border-2 text-right transition-colors duration-200 min-h-[68px] touch-target disabled:cursor-not-allowed disabled:opacity-60 ${
              isSelected ? style.active : style.idle
            }`}
          >
            {/* آیکون دسته */}
            <span
              className={`flex-shrink-0 w-11 h-11 rounded-2xl flex items-center justify-center p-2 text-xl transition-colors duration-200 ${
                isSelected ? style.iconActive : style.iconIdle
              }`}
              aria-hidden="true"
            >
              <SiteImage
                imageKey={style.iconKey}
                fallback={style.icon}
                alt=""
                className="w-full h-full object-contain"
              />
            </span>

            {/* متن */}
            <div className="flex-1 min-w-0">
              <div
                className={`text-sm font-black leading-tight transition-colors duration-200 ${
                  isSelected
                    ? style.textActive
                    : 'text-ink-900 dark:text-cream-100'
                }`}
              >
                {category.name}
              </div>
              <div
                className={`text-[11px] mt-0.5 leading-relaxed truncate font-bold transition-colors duration-200 ${
                  isSelected
                    ? style.subActive
                    : 'text-ink-500 dark:text-cream-400'
                }`}
              >
                {category.description}
              </div>
            </div>

            {/* چک‌باکس */}
            <span
              className={`flex-shrink-0 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors duration-200 ${
                isSelected ? style.checkActive : `${style.checkIdle}`
              }`}
              aria-hidden="true"
            >
              <SiteImage
                imageKey="icon_check"
                fallback="✓"
                alt=""
                className={`w-3.5 h-3.5 object-contain transition-all duration-200 ${
                  isSelected
                    ? 'opacity-100 brightness-0 invert'
                    : 'opacity-0'
                }`}
              />
            </span>
          </button>
        );
      })}
    </div>
  );
}