// frontend/src/user/components/Toast.jsx
import React, { useEffect, useState, useCallback, useRef } from 'react';
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  ⚙️ Constants
// ============================================================
const DEFAULT_DURATION = 3500;
const MAX_QUEUE_SIZE = 5;

// ============================================================
//  🎨 Config: success | error | warning | info
// ============================================================
const TOAST_CONFIG = {
  success: {
    icon: '✓',
    iconKey: 'icon_check',
    label: 'موفق',
    role: 'status',
    ariaLive: 'polite',
    strip: 'bg-accent-500',
    iconBg: 'bg-accent-100 dark:bg-accent-500/25 text-accent-700 dark:text-accent-300',
    titleColor: 'text-accent-800 dark:text-accent-200',
    border: 'border-accent-200 dark:border-accent-500/30',
    progress: 'bg-accent-500',
  },
  error: {
    icon: '!',
    iconKey: 'icon_error',
    label: 'خطا',
    role: 'alert',
    ariaLive: 'assertive',
    strip: 'bg-rose-500',
    iconBg: 'bg-rose-100 dark:bg-rose-500/25 text-rose-700 dark:text-rose-300',
    titleColor: 'text-rose-800 dark:text-rose-200',
    border: 'border-rose-200 dark:border-rose-500/30',
    progress: 'bg-rose-500',
  },
  warning: {
    icon: '⚠',
    iconKey: 'icon_warning',
    label: 'هشدار',
    role: 'alert',
    ariaLive: 'polite',
    strip: 'bg-brand-500',
    iconBg: 'bg-brand-100 dark:bg-brand-500/25 text-brand-700 dark:text-brand-300',
    titleColor: 'text-brand-800 dark:text-brand-200',
    border: 'border-brand-200 dark:border-brand-500/30',
    progress: 'bg-brand-500',
  },
  info: {
    icon: 'i',
    iconKey: 'icon_info',
    label: 'اطلاع',
    role: 'status',
    ariaLive: 'polite',
    strip: 'bg-ink-500',
    iconBg: 'bg-ink-100 dark:bg-ink-700 text-ink-700 dark:text-cream-200',
    titleColor: 'text-ink-800 dark:text-cream-100',
    border: 'border-ink-200 dark:border-dark-600',
    progress: 'bg-ink-500',
  },
};

const POSITION_CLASSES = {
  default: 'bottom-4 sm:bottom-6',
  'above-nav': 'bottom-20 sm:bottom-6',
  top: 'top-4 sm:top-6',
  'top-above-nav': 'top-16 sm:top-6',
};

// ============================================================
//  🎬 Keyframes
// ============================================================
function ToastKeyframes() {
  return (
    <style>{`
      @keyframes toast-progress {
        from { transform: scaleX(1); }
        to   { transform: scaleX(0); }
      }
    `}</style>
  );
}

// ============================================================
//  🎨 ToastView
// ============================================================
export function ToastView({
  type = 'info',
  message,
  onClose,
  action,
  offset = 'default',
  duration = 0,
  paused = false,
  onMouseEnter,
  onMouseLeave,
  onTouchStart,
  onTouchEnd,
}) {
  const cfg = TOAST_CONFIG[type] || TOAST_CONFIG.info;
  const positionClass = POSITION_CLASSES[offset] || POSITION_CLASSES.default;
  const hasDuration = duration > 0;

  return (
    <div
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      onTouchStart={onTouchStart}
      onTouchEnd={onTouchEnd}
      className={`
        fixed left-1/2 -translate-x-1/2 z-[80]
        ${positionClass}
        w-[calc(100%-2rem)] sm:w-auto sm:max-w-md
        bg-paper-50 dark:bg-ink-800
        border-2 ${cfg.border}
        rounded-2xl
        shadow-editorial
        overflow-hidden
        animate-slide-up
      `}
      role={cfg.role}
      aria-live={cfg.ariaLive}
      aria-atomic="true"
      dir="rtl"
    >
      <div className="relative flex items-stretch">
        <div className={`w-1.5 ${cfg.strip} flex-shrink-0`} aria-hidden="true" />

        <div className="flex-1 flex items-start gap-3 p-4 sm:p-5 min-w-0">
          <div
            className={`flex-shrink-0 w-10 h-10 rounded-2xl flex items-center justify-center p-2 text-lg font-black ${cfg.iconBg}`}
            aria-hidden="true"
          >
            <SiteImage
              imageKey={cfg.iconKey}
              fallback={cfg.icon}
              alt=""
              className="w-full h-full object-contain"
            />
          </div>

          <div className="flex-1 min-w-0 pt-0.5">
            <div
              className={`font-display font-black text-[10px] uppercase tracking-[0.15em] mb-1 ${cfg.titleColor}`}
            >
              {cfg.label}
            </div>
            <div className="text-sm text-ink-800 dark:text-cream-100 leading-relaxed break-safe">
              {message}
            </div>

            {action && (
              <button
                type="button"
                onClick={action.onClick}
                className="mt-3 min-h-[36px] inline-flex items-center gap-1.5 px-3.5 py-1.5 bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 hover:opacity-90 active:opacity-80 rounded-xl text-xs font-black transition-all touch-target"
                title={action.label}
              >
                <span>{action.label}</span>
                <span aria-hidden="true">←</span>
              </button>
            )}
          </div>

          {onClose && (
            <button
              type="button"
              onClick={onClose}
              className="flex-shrink-0 w-8 h-8 flex items-center justify-center rounded-xl text-ink-400 dark:text-cream-400 hover:text-ink-700 dark:hover:text-cream-100 hover:bg-ink-100 dark:hover:bg-ink-700/60 active:bg-ink-200 dark:active:bg-ink-700 transition text-base touch-target"
              title="بستن"
              aria-label="بستن اعلان"
            >
              ✕
            </button>
          )}
        </div>
      </div>

      {hasDuration && (
        <div
          className="absolute bottom-0 left-0 right-0 h-0.5 bg-ink-200/40 dark:bg-ink-700/40 overflow-hidden"
          aria-hidden="true"
        >
          <div
            className={`h-full w-full ${cfg.progress} origin-right`}
            style={{
              animation: `toast-progress ${duration}ms linear forwards`,
              animationPlayState: paused ? 'paused' : 'running',
            }}
          />
        </div>
      )}
    </div>
  );
}

// ============================================================
//  🔗 Active Dispatcher — ✅ FIX (مشکل ۱): State Sharing
//
//  قبلاً هر useToast() یک state جدا داشت. حالا:
//  - <ToastHost /> خودش را به عنوان dispatcher فعال ثبت می‌کند
//  - هر useToast().showToast از هر جای دیگر به آن delegate می‌شود
//  - اگر هیچ <ToastHost /> mount نباشد → fallback به local state
//    (مثل Pattern B در UserLogin)
// ============================================================
let activeDispatcher = null;
let globalToastFn = null;

// ============================================================
//  🎣 useToast
// ============================================================
export function useToast(defaultDuration = DEFAULT_DURATION) {
  const [toast, setToast] = useState(null);
  const [paused, setPaused] = useState(false);

  const queueRef = useRef([]);
  const timeoutRef = useRef(null);
  const remainingRef = useRef(0);
  const startTimeRef = useRef(0);
  const isMountedRef = useRef(true);
  const lastToastIdRef = useRef(null);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      queueRef.current = [];
    };
  }, []);

  useEffect(() => {
    setPaused(false);
  }, [toast?.id]);

  // ===== Auto-hide timer — ✅ FIX (باگ pause) =====
  useEffect(() => {
    if (!toast) {
      if (queueRef.current.length === 0) return;
      const next = queueRef.current.shift();
      setToast(next);
      return;
    }

    const duration = toast.duration ?? defaultDuration;
    if (duration <= 0) return;

    // ✅ FIX: فقط برای toast جدید مقداردهی کن، نه هنگام pause toggle
    if (lastToastIdRef.current !== toast.id) {
      lastToastIdRef.current = toast.id;
      remainingRef.current = duration;
      startTimeRef.current = Date.now();
    }

    const startTimer = () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
        if (isMountedRef.current) setToast(null);
      }, remainingRef.current);
    };

    if (!paused) {
      startTimer();
    }

    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, [toast, defaultDuration, paused]);

  const handlePause = useCallback(() => {
    if (!toast) return;
    const duration = toast.duration ?? defaultDuration;
    if (duration <= 0) return;

    const elapsed = Date.now() - startTimeRef.current;
    remainingRef.current = Math.max(80, remainingRef.current - elapsed);
    setPaused(true);
  }, [toast, defaultDuration]);

  const handleResume = useCallback(() => {
    if (!toast) return;
    startTimeRef.current = Date.now();
    setPaused(false);
  }, [toast]);

  // ============================================================
  //  ✅ FIX: Local show (updates THIS hook's state)
  // ============================================================
  const showToastLocal = useCallback((type, message, options = {}) => {
    const newToast = {
      id: Date.now() + Math.random(),
      type,
      message,
      duration: options.duration,
      action: options.action,
    };

    setToast((prev) => {
      // Dedup
      if (prev && prev.message === message && prev.type === type) {
        return prev;
      }

      if (queueRef.current.length >= MAX_QUEUE_SIZE) {
        queueRef.current.shift();
      }

      if (prev) {
        queueRef.current.push(newToast);
        return prev;
      }

      return newToast;
    });
  }, []);

  // ============================================================
  //  ✅ FIX: Public show — if a ToastHost is mounted elsewhere,
  //  delegate to it so the toast actually renders.
  // ============================================================
  const showToast = useCallback((type, message, options = {}) => {
    if (activeDispatcher && activeDispatcher !== showToastLocal) {
      activeDispatcher(type, message, options);
      return;
    }
    showToastLocal(type, message, options);
  }, [showToastLocal]);

  const hideToast = useCallback(() => {
    setPaused(false);
    setToast(null);
  }, []);

  return {
    toast,
    showToast,
    showToastLocal,   // exposed for ToastHost registration
    hideToast,
    paused,
    handlePause,
    handleResume,
  };
}

// ============================================================
//  🌐 ToastHost — registers as active dispatcher
// ============================================================
export function ToastHost({ offset = 'default' }) {
  const {
    toast,
    showToastLocal,
    hideToast,
    paused,
    handlePause,
    handleResume,
  } = useToast();

  // ✅ Register as active dispatcher + global API
  useEffect(() => {
    activeDispatcher = showToastLocal;
    globalToastFn = {
      success: (msg, opts) => showToastLocal('success', msg, opts),
      error: (msg, opts) => showToastLocal('error', msg, opts),
      info: (msg, opts) => showToastLocal('info', msg, opts),
      warning: (msg, opts) => showToastLocal('warning', msg, opts),
    };
    return () => {
      if (activeDispatcher === showToastLocal) activeDispatcher = null;
      globalToastFn = null;
    };
  }, [showToastLocal]);

  if (!toast) return null;

  const duration = toast.duration ?? DEFAULT_DURATION;

  return (
    <>
      <ToastKeyframes />
      <ToastView
        {...toast}
        onClose={hideToast}
        offset={offset}
        duration={duration}
        paused={paused}
        onMouseEnter={handlePause}
        onMouseLeave={handleResume}
        onTouchStart={handlePause}
        onTouchEnd={handleResume}
      />
    </>
  );
}

// ============================================================
//  🌍 Global API — usable from anywhere (requires ToastHost mounted)
// ============================================================
export const toast = {
  success: (msg, opts) => globalToastFn?.success(msg, opts),
  error: (msg, opts) => globalToastFn?.error(msg, opts),
  info: (msg, opts) => globalToastFn?.info(msg, opts),
  warning: (msg, opts) => globalToastFn?.warning(msg, opts),
};

export default ToastView;