const getAllergensFromDog = (dog) => {
  if (!dog) return [];
  if (Array.isArray(dog.allergens) && dog.allergens.length > 0) {
    return dog.allergens.filter((a) => a);
  }
  const result = [];
  const seen = new Set();
  const atype = (dog.allergy_type || '').trim().toLowerCase();
  if (atype && atype !== 'none' && atype !== 'multiple') {
    result.push(atype);
    seen.add(atype);
  }
  const details = (dog.allergy_details || '').trim();
  if (details) {
    let d = details;
    for (const sep of [',', '،', ';', '؛']) {
      d = d.replace(sep, ',');
    }
    for (const p of d.split(',')) {
      const norm = p.trim().toLowerCase().replace(/\s+/g, '_');
      if (norm && norm !== 'none' && !seen.has(norm)) {
        seen.add(norm);
        result.push(norm);
      }
    }
  }
  return result;
};

const captureScrollPosition = () => {
  try {
    const y = window.scrollY || window.pageYOffset || 0;
    sessionStorage.setItem(SCROLL_RESTORE_KEY, String(y));
    sessionStorage.setItem(SCROLL_RESTORE_FLAG, '1');
  } catch {
    /* silent */
  }
};

const toPersianFormValue = (name, raw) => {
  if (raw === null || raw === undefined || raw === '') return '';
  const str = String(raw);
  if (name === 'weight_kg') return toFaNumberInput(str);
  if (name === 'age_months' || name === 'days_count') return toFaDigits(str);
  return raw;
};

