function BCSGuideCard({ value }) {
  const guide = BCS_GUIDE[value] || BCS_GUIDE.ideal;
  const colors = BCS_COLORS[guide.color] || BCS_COLORS.brand;
  const label = BCS_OPTIONS.find((o) => o.value === value)?.label || 'وضعیت بدنی';

  return (
    <div className={`mt-1.5 ${colors.bg} border ${colors.border} rounded-xl p-2 flex items-start gap-2`} role="note">
      <span className="text-base flex-shrink-0" aria-hidden="true">{guide.emoji}</span>
      <div className="flex-1 min-w-0">
        <div className={`text-xs font-black ${colors.text} mb-0.5`}>{label}</div>
        <div className={`text-xs ${colors.text} opacity-90 leading-relaxed`}>{guide.desc}</div>
      </div>
    </div>
  );
}

function ChoiceGrid({ options, value, onChange, columns = 3, compact = false }) {
  const gridCols = columns === 1
    ? 'grid-cols-1'
    : columns === 2
      ? 'grid-cols-2'
      : columns === 3
        ? 'grid-cols-2 lg:grid-cols-3'
        : columns === 4
          ? 'grid-cols-2 sm:grid-cols-4'
          : 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5';

  return (
    <div className={`grid ${gridCols} gap-2 sm:gap-3`}>
      {options.map((option) => {
        const selected = String(value) === String(option.value);
        return (
          <button
            key={option.value}
            type="button"
            onClick={() => onChange(option.value)}
            aria-pressed={selected}
            className={`group relative ${compact ? 'min-h-[44px] p-2' : 'min-h-[46px] p-2.5 sm:p-3'} min-w-0 rounded-xl border text-right transition-colors duration-150 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500/30 ${
              selected
                ? 'border-brand-600 bg-brand-50 shadow-sm dark:border-brand-400 dark:bg-brand-500/10'
                : 'border-ink-200 bg-white hover:border-brand-300 hover:bg-paper-50 dark:border-white/10 dark:bg-white/[0.03] dark:hover:border-brand-500/50 dark:hover:bg-white/[0.06]'
            }`}
          >
            <span className="flex min-w-0 items-center justify-between gap-2">
              <span className={`min-w-0 text-xs font-bold leading-5 sm:text-sm ${selected ? 'text-brand-900 dark:text-brand-200' : 'text-ink-800 dark:text-ink-100'}`}>
                {option.label}
              </span>
              <span className={`flex h-4 w-4 shrink-0 items-center justify-center rounded-full border transition sm:h-5 sm:w-5 ${
                selected
                  ? 'border-brand-600 bg-brand-600 text-white dark:border-brand-400 dark:bg-brand-400 dark:text-ink-950'
                  : 'border-ink-300 text-transparent dark:border-white/20'
              }`} aria-hidden="true">
                <svg viewBox="0 0 20 20" className="h-3 w-3 sm:h-3.5 sm:w-3.5" fill="none">
                  <path d="m4 10 4 4 8-8" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" />
                </svg>
              </span>
            </span>
            {option.description && (
              <span className={`mt-1 hidden text-xs leading-5 lg:block ${selected ? 'text-brand-800/80 dark:text-brand-200/80' : 'text-ink-500 dark:text-ink-400'}`}>
                {option.description}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

