// frontend/src/user/components/SiteFooter.jsx
// ============================================================
//  🐾 SiteFooter v14 — Miko Warm Palette
//  ✅ v14.1: بازبینی شد — از ابتدا ۱۰۰٪ با SiteImage پیاده‌سازی شده بود
//  - آیکون‌های شبکه‌های اجتماعی و تماس با SVG به عنوان placeholderContent
//  - همهٔ آیکون‌ها از پنل ادمین قابل مدیریت هستند
// ============================================================

import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { toFaDate } from '../../utils/numbers';
import { SiteImage } from '../../utils/SiteImage';

// ============================================================
//  🌐 آیکون‌های SVG (Fallback برای SiteImage)
// ============================================================
const InstagramIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-full h-full">
    <rect x="2" y="2" width="20" height="20" rx="5" ry="5" />
    <path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z" />
    <line x1="17.5" y1="6.5" x2="17.51" y2="6.5" />
  </svg>
);

const TelegramIcon = () => (
  <svg viewBox="0 0 24 24" fill="currentColor" className="w-full h-full">
    <path d="M9.04 15.51l-.39 5.5c.56 0 .8-.24 1.09-.52l2.62-2.5 5.42 3.97c.99.55 1.7.26 1.96-.92L22.9 4.55c.32-1.47-.53-2.04-1.5-1.67L2.28 9.93c-1.42.56-1.4 1.35-.24 1.71l4.9 1.53 11.34-7.16c.53-.35 1.02-.16.62.19l-9.86 9.31z" />
  </svg>
);

const WhatsappIcon = () => (
  <svg viewBox="0 0 24 24" fill="currentColor" className="w-full h-full">
    <path d="M17.47 14.38c-.3-.15-1.76-.87-2.03-.97-.27-.1-.47-.15-.67.15-.2.3-.77.97-.94 1.17-.17.2-.35.22-.64.07-.3-.15-1.25-.46-2.38-1.47-.88-.78-1.47-1.75-1.65-2.05-.17-.3-.02-.46.13-.6.14-.14.3-.35.45-.52.15-.17.2-.3.3-.5.1-.2.05-.37-.02-.52-.07-.15-.65-1.56-.88-2.14-.23-.56-.46-.48-.64-.49l-.54-.01c-.19 0-.5.07-.76.37-.26.3-1 .97-1 2.36 0 1.4 1.02 2.74 1.16 2.94.15.2 2 3.06 4.85 4.29.68.29 1.2.47 1.62.6.68.22 1.3.19 1.79.11.54-.08 1.66-.68 1.9-1.34.23-.65.23-1.21.16-1.34-.07-.13-.26-.2-.55-.35zM12 2C6.48 2 2 6.48 2 12c0 1.88.52 3.65 1.42 5.16L2 22l4.99-1.31A9.94 9.94 0 0 0 12 22c5.52 0 10-4.48 10-10S17.52 2 12 2z" />
  </svg>
);

const PhoneIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-full h-full">
    <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z" />
  </svg>
);

const MailIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="w-full h-full">
    <rect width="20" height="16" x="2" y="4" rx="2" />
    <path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7" />
  </svg>
);

// ============================================================
//  📋 داده‌ها
// ============================================================
const QUICK_LINKS = [
  { label: 'صفحه اصلی', href: '/' },
  { label: 'محاسبه رژیم', href: '/#quick-calculator' },
  { label: 'چرا میکو؟', href: '/#benefits' },
  { label: 'سؤالات متداول', href: '/#faq' },
];

const SUPPORT_LINKS = [
  { label: 'پنل کاربری', href: '/panel' },
  { label: 'پیگیری سفارش', href: '/panel/orders' },
  { label: 'ارسال تیکت', href: '/panel/tickets/new' },
  { label: 'ثبت نظر', href: '/panel/testimonials/new' },
];

// ============================================================
//  🎯 کامپوننت اصلی
// ============================================================
export default function SiteFooter() {
  const location = useLocation();
  const persianYear = toFaDate(new Date(), { year: 'numeric' }, '');

  const handleNavClick = (e, href) => {
    if (href === '/') {
      if (location.pathname === '/') {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
      }
    } else if (href.startsWith('/#')) {
      const id = href.replace('/#', '');
      const el = document.getElementById(id);
      if (el) {
        e.preventDefault();
        const top = el.getBoundingClientRect().top + window.pageYOffset - 80;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    }
  };

  return (
    <footer className="relative bg-miko-rust pt-10 pb-6 sm:pt-16 sm:pb-10" role="contentinfo">
      <div className="mx-auto max-w-6xl px-4 sm:px-6 lg:px-8">

        {/* کارت کرم رنگ فوتر */}
        <div className="overflow-hidden rounded-[1.5rem] bg-miko-cream shadow-2xl sm:rounded-[2rem]">
          {/* خط نارنجی هویج بالای کارت */}
          <div className="h-1.5 w-full bg-miko-carrot" />

          <div className="p-6 sm:p-8 lg:p-10">
            <div className="grid grid-cols-1 md:grid-cols-12 gap-8 md:gap-6">

              {/* ۱. برند (۵ ستون) */}
              <div className="md:col-span-5 flex flex-col items-start">
                <Link
                  to="/"
                  onClick={(e) => handleNavClick(e, '/')}
                  className="flex items-center gap-3 group mb-4"
                >
                  <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-miko-rust shadow-sm overflow-hidden p-1.5 transition-transform group-hover:scale-105">
                    <SiteImage
                      imageKey="footer_logo"
                      fallback=""
                      alt="لوگوی میکو"
                      className="w-full h-full object-contain"
                      placeholderContent={<span className="font-miko text-2xl text-miko-cream">م</span>}
                      showPlaceholder={true}
                    />
                  </div>
                  <div>
                    <div className="font-miko text-3xl leading-none text-miko-rust">میکو</div>
                    <div className="text-[10px] font-black tracking-[0.2em] text-miko-olive mt-1">
                      SMALL BATCH · TEHRAN
                    </div>
                  </div>
                </Link>
                <p className="text-[13px] sm:text-sm font-semibold text-miko-dark/80 leading-6 max-w-[280px]">
                  غذای خانگی تازه و اختصاصی برای سلامت و شادی رفیق پشمالوی شما.
                </p>

                {/* شبکه‌های اجتماعی — هماهنگ با پالت میکو */}
                <div className="mt-5 flex items-center gap-2.5">
                  <a href="https://instagram.com/" target="_blank" rel="noopener noreferrer" className="group flex h-10 w-10 items-center justify-center rounded-full border border-miko-carrot/30 bg-white text-miko-olive transition-all hover:-translate-y-1 hover:border-miko-rust hover:bg-miko-rust hover:text-white" aria-label="اینستاگرام">
                    <div className="w-4 h-4">
                      <SiteImage imageKey="icon_instagram" fallback="" alt="" className="w-full h-full object-contain" placeholderContent={<InstagramIcon />} showPlaceholder={true} />
                    </div>
                  </a>
                  <a href="https://t.me/" target="_blank" rel="noopener noreferrer" className="group flex h-10 w-10 items-center justify-center rounded-full border border-miko-carrot/30 bg-white text-miko-olive transition-all hover:-translate-y-1 hover:border-miko-rust hover:bg-miko-rust hover:text-white" aria-label="تلگرام">
                    <div className="w-4 h-4">
                      <SiteImage imageKey="icon_telegram" fallback="" alt="" className="w-full h-full object-contain" placeholderContent={<TelegramIcon />} showPlaceholder={true} />
                    </div>
                  </a>
                  <a href="https://wa.me/" target="_blank" rel="noopener noreferrer" className="group flex h-10 w-10 items-center justify-center rounded-full border border-miko-carrot/30 bg-white text-miko-olive transition-all hover:-translate-y-1 hover:border-miko-rust hover:bg-miko-rust hover:text-white" aria-label="واتساپ">
                    <div className="w-4 h-4">
                      <SiteImage imageKey="icon_whatsapp" fallback="" alt="" className="w-full h-full object-contain" placeholderContent={<WhatsappIcon />} showPlaceholder={true} />
                    </div>
                  </a>
                </div>
              </div>

              {/* ۲. لینک‌ها (۴ ستون) */}
              <div className="md:col-span-4 grid grid-cols-2 gap-4">
                <div>
                  <h4 className="mb-4 font-display text-sm font-black text-miko-rust">دسترسی سریع</h4>
                  <ul className="space-y-3">
                    {QUICK_LINKS.map((link, idx) => (
                      <li key={idx}>
                        <Link
                          to={link.href}
                          onClick={(e) => handleNavClick(e, link.href)}
                          className="text-[13px] font-bold text-miko-dark/80 transition-colors hover:text-miko-rust"
                        >
                          {link.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
                <div>
                  <h4 className="mb-4 font-display text-sm font-black text-miko-rust">پشتیبانی</h4>
                  <ul className="space-y-3">
                    {SUPPORT_LINKS.map((link, idx) => (
                      <li key={idx}>
                        <Link
                          to={link.href}
                          className="text-[13px] font-bold text-miko-dark/80 transition-colors hover:text-miko-rust"
                        >
                          {link.label}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              {/* ۳. تماس (۳ ستون) */}
              <div className="md:col-span-3">
                <h4 className="mb-4 font-display text-sm font-black text-miko-rust">تماس با ما</h4>
                <ul className="space-y-3">
                  <li>
                    <a href="tel:09121234567" className="group flex items-center gap-3 text-sm font-bold text-miko-dark/80 hover:text-miko-rust transition-colors">
                      <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-white border border-miko-carrot/30 text-miko-carrot group-hover:border-miko-carrot group-hover:text-miko-rust transition-colors">
                        <div className="w-4 h-4">
                          <SiteImage imageKey="icon_phone" fallback="" alt="" className="w-full h-full object-contain" placeholderContent={<PhoneIcon />} showPlaceholder={true} />
                        </div>
                      </div>
                      <span dir="ltr">۰۹۱۲ ۱۲۳ ۴۵۶۷</span>
                    </a>
                  </li>
                  <li>
                    <a href="mailto:support@miko.ir" className="group flex items-center gap-3 text-sm font-bold text-miko-dark/80 hover:text-miko-rust transition-colors">
                      <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-white border border-miko-carrot/30 text-miko-carrot group-hover:border-miko-carrot group-hover:text-miko-rust transition-colors">
                        <div className="w-4 h-4">
                          <SiteImage imageKey="icon_email" fallback="" alt="" className="w-full h-full object-contain" placeholderContent={<MailIcon />} showPlaceholder={true} />
                        </div>
                      </div>
                      <span dir="ltr">support@miko.ir</span>
                    </a>
                  </li>
                </ul>
              </div>
            </div>

            {/* پایین فوتر */}
            <div className="mt-10 flex flex-col sm:flex-row items-center justify-between gap-4 border-t border-miko-carrot/20 pt-6">
              <p className="text-xs font-bold text-miko-dark/70">
                © {persianYear} میکو — تمامی حقوق محفوظ است.
              </p>
              <div className="flex items-center gap-2">
                {['NRC 2006', 'AAFCO 2024'].map((item) => (
                  <span key={item} className="rounded-lg border border-miko-olive/30 bg-white px-2.5 py-1 text-[10px] font-black text-miko-olive" dir="ltr">
                    {item}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </footer>
  );
}