// frontend/src/admin/components/SiteImagesManager.jsx
import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import axios from '../axiosConfig';
import { API_BASE } from '../../config/api';
import { invalidateSiteImageCache } from '../../utils/SiteImage';
import { toFa, toFaDecimal } from '../../utils/numbers';

// ============================================================
//  🧠 دسته‌بندی منطقی (Logical Categorization)
//  به جای استفاده از کتگوری‌های خشک بک‌اند، بر اساس کلید (key)
//  تشخیص می‌دیم که این آیکون متعلق به کدوم بخش سایته.
// ============================================================
const LOGICAL_TABS = [
  { key: 'all', label: 'همه تصاویر', icon: '🗂️' },
  { key: 'landing', label: 'صفحه اصلی', icon: '🏠' },
  { key: 'user_panel', label: 'پنل کاربر', icon: '👤' },
  { key: 'admin_panel', label: 'پنل ادمین', icon: '⚙️' },
  { key: 'brand', label: 'لوگوها و برندینگ', icon: '🏷️' },
  { key: 'auth', label: 'ورود / ثبت‌نام', icon: '🔐' },
  { key: 'other', label: 'آیکون‌ها و استیکرهای عمومی', icon: '✨' },
];

const getLogicalCategory = (img) => {
  const k = (img.key || '').toLowerCase();
  const c = (img.category || '').toLowerCase();

  // ۱. لوگوها و برندینگ
  if (c === 'brand' || k.includes('logo') || k.includes('brand')) {
    return 'brand';
  }

  // ۲. احراز هویت (ورود/ثبت‌نام)
  if (
    c === 'auth' ||
    k.includes('login') ||
    k.includes('register') ||
    k.includes('auth')
  ) {
    return 'auth';
  }

  // ۳. پنل ادمین
  if (
    k.includes('admin') ||
    k.includes('dashboard') ||
    k.includes('setting') ||
    k.includes('factor') ||
    k.includes('ingredient') ||
    k.includes('store') ||
    k.includes('users') ||
    k.includes('factory') ||
    k.includes('money') ||
    k.includes('image_') ||
    k.includes('map') ||
    k.includes('flask') ||
    k.includes('ruler') ||
    k.includes('chef') ||
    k.includes('pot')
  ) {
    return 'admin_panel';
  }

  // ۴. پنل کاربر
  if (
    k.includes('user_') ||
    k.includes('dog_avatar') ||
    k.includes('ticket') ||
    k.includes('profile') ||
    k.includes('cart') ||
    k.includes('receipt') ||
    k.includes('payment_') ||
    k.includes('empty_state') ||
    k.includes('dashboard_welcome') ||
    k.includes('avatar')
  ) {
    return 'user_panel';
  }

  // ۵. صفحه اصلی (Landing)
  if (
    k.includes('hero') ||
    k.includes('benefit') ||
    k.includes('trust') ||
    k.includes('kpi') ||
    k.includes('testimonial') ||
    k.includes('faq') ||
    k.includes('footer_') ||
    k.includes('how_it_works') ||
    k.includes('order_form') ||
    k.includes('home')
  ) {
    return 'landing';
  }

  // ۶. آیکون‌ها و استیکرهای عمومی (ستاره، پنجه، قلب، وضعیت سفارش و...)
  return 'other';
};

// ============================================================
//  🎨 تنظیمات اصلی
// ============================================================
const MAX_FILE_SIZE_MB = 3;
const MAX_FILE_SIZE = MAX_FILE_SIZE_MB * 1024 * 1024;

// ✅ FIX: SVG حذف شد (ریسک XSS)
const ALLOWED_EXTS = ['.jpg', '.jpeg', '.png', '.webp', '.gif'];
const ACCEPT_STRING = '.jpg,.jpeg,.png,.webp,.gif';

const DEFAULT_IMAGE_SETTINGS = {
  object_fit: 'cover',
  zoom: 100,
  pos_x: 50,
  pos_y: 50,
};

const CATEGORY_LABELS = {
  hero: 'صفحه اصلی (Hero)',
  background: 'بک‌گراندها',
  auth: 'صفحات ورود/ثبت‌نام',
  sticker: 'استیکرها',
  icon: 'آیکون‌ها',
  footer: 'فوتر',
  brand: 'برندینگ / لوگو',
  other: 'سایر',
};

const OBJECT_FIT_OPTIONS = [
  { value: 'cover', label: 'cover — پر کردن کادر (برش اضافه‌ها)' },
  { value: 'contain', label: 'contain — کامل نمایش داده شود' },
  { value: 'fill', label: 'fill — کشیده شود (ممکن است اعوجاج بده)' },
  { value: 'none', label: 'none — اندازه اصلی، بدون تغییر' },
  { value: 'scale-down', label: 'scale-down — کوچک‌تر از تصویر اصلی' },
];

// ============================================================
//  🛠️ Helper Functions
// ============================================================
function formatBytes(bytes) {
  const n = Number(bytes) || 0;
  if (n < 1024) return `${toFa(n)} B`;
  if (n < 1024 * 1024) return `${toFaDecimal(n / 1024, 1)} KB`;
  return `${toFaDecimal(n / (1024 * 1024), 2)} MB`;
}

function validateFile(file) {
  if (!file) return 'فایلی انتخاب نشده است';
  const ext = '.' + (file.name.split('.').pop() || '').toLowerCase();
  if (!ALLOWED_EXTS.includes(ext)) return `پسوند ${ext} مجاز نیست.`;
  if (file.size > MAX_FILE_SIZE) return `حجم فایل بیش از ${toFa(MAX_FILE_SIZE_MB)} مگابایت است`;
  return null;
}

function buildImageStyle(settings) {
  const objectFit = settings.object_fit ?? DEFAULT_IMAGE_SETTINGS.object_fit;
  const zoom = settings.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom;
  const posX = settings.pos_x ?? DEFAULT_IMAGE_SETTINGS.pos_x;
  const posY = settings.pos_y ?? DEFAULT_IMAGE_SETTINGS.pos_y;

  const style = { objectFit, objectPosition: `${posX}% ${posY}%` };
  if (zoom !== 100 && zoom > 0) {
    style.transform = `scale(${zoom / 100})`;
    style.transformOrigin = `${posX}% ${posY}%`;
  }
  return style;
}

// ============================================================
//  🖼️ ImageCard (کارت فشرده و کوچک)
// ============================================================
function ImageCard({ image, onEdit, onToggleActive, onQuickUpload, onCopyUsage, saving }) {
  const isActive = image.is_active !== false;
  const hasImage = image.url && image.url !== '';
  const fileInputRef = useRef(null);

  const handleQuickUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    onQuickUpload(image, file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className={`group relative flex flex-col overflow-hidden rounded-xl border transition-all ${
      isActive
        ? 'bg-white dark:bg-ink-800 border-ink-200 dark:border-dark-700 hover:border-brand-400 hover:shadow-md'
        : 'bg-ink-50 dark:bg-ink-900/50 border-ink-200 dark:border-dark-700 opacity-60'
    }`}>

      {/* تصویر یا ایموجی */}
      <div className="relative aspect-square bg-ink-50 dark:bg-ink-900/50 flex items-center justify-center overflow-hidden p-2">
        {hasImage ? (
          <img
            src={`${API_BASE}${image.url}`}
            alt={image.title}
            className="w-full h-full rounded-lg"
            style={buildImageStyle(image)}
            loading="lazy"
          />
        ) : (
          <div className="text-4xl" title="تصویر پیش‌فرض (ایموجی)">
            {image.fallback || '🖼️'}
          </div>
        )}

        {/* نشانگر فعال/غیرفعال */}
        <div className="absolute top-2 right-2">
          <span className={`block w-2.5 h-2.5 rounded-full shadow-sm ${isActive ? 'bg-accent-500' : 'bg-ink-400'}`} />
        </div>

        {/* برچسب دسته‌بندی اصلی بک‌اند (کوچک) */}
        <div className="absolute top-2 left-2">
          <span className="bg-black/50 text-white backdrop-blur-sm text-[8px] px-1.5 py-0.5 rounded">
            {CATEGORY_LABELS[image.category] || image.category}
          </span>
        </div>
      </div>

      {/* اطلاعات و دکمه‌ها */}
      <div className="p-2.5 flex-1 flex flex-col border-t border-ink-100 dark:border-dark-700">
        <div className="font-bold text-xs text-ink-900 dark:text-cream-100 truncate mb-0.5" title={image.title}>
          {image.title}
        </div>
        <div className="font-mono text-[9px] text-ink-500 truncate mb-2" dir="ltr" title={image.key}>
          {image.key}
        </div>

        {/* دکمه‌های عملیات */}
        <div className="mt-auto flex items-center justify-between gap-1 border-t border-ink-100 dark:border-dark-700 pt-2">
          <div className="flex gap-1">
            <button
              onClick={() => fileInputRef.current?.click()}
              disabled={saving}
              className="w-7 h-7 flex items-center justify-center rounded bg-brand-50 text-brand-600 hover:bg-brand-100 transition"
              title={hasImage ? "تغییر عکس" : "آپلود عکس"}
            >
              {hasImage ? '🔄' : '📷'}
            </button>
            <input ref={fileInputRef} type="file" accept={ACCEPT_STRING} onChange={handleQuickUpload} className="hidden" />

            <button
              onClick={() => onEdit(image)}
              disabled={saving}
              className="w-7 h-7 flex items-center justify-center rounded bg-ink-100 dark:bg-ink-700 text-ink-600 dark:text-cream-200 hover:bg-ink-200 dark:hover:bg-ink-600 transition"
              title="تنظیمات نمایش (زوم/موقعیت)"
            >
              ⚙️
            </button>
          </div>

          <div className="flex gap-1">
            <button
              onClick={() => onToggleActive(image.id)}
              disabled={saving}
              className={`w-7 h-7 flex items-center justify-center rounded transition ${isActive ? 'bg-rose-50 text-rose-500 hover:bg-rose-100' : 'bg-green-50 text-green-600 hover:bg-green-100'}`}
              title={isActive ? 'غیرفعال کردن' : 'فعال کردن'}
            >
              {isActive ? '🚫' : '✅'}
            </button>
            <button
              onClick={() => onCopyUsage(image)}
              disabled={saving}
              className="w-7 h-7 flex items-center justify-center rounded bg-purple-50 text-purple-600 hover:bg-purple-100 transition font-mono text-[9px]"
              title="کپی کد استفاده"
            >
              {'</>'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  🚀 کامپوننت اصلی
// ============================================================
export default function SiteImagesManager({ showToast }) {
  const [images, setImages] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [activeTab, setActiveTab] = useState('all');
  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const [formOpen, setFormOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState({
    key: '', title: '', description: '', category: 'other', alt_text: '', is_active: true,
    ...DEFAULT_IMAGE_SETTINGS,
  });
  const [formFile, setFormFile] = useState(null);
  const [formFilePreview, setFormFilePreview] = useState(null);
  const [formError, setFormError] = useState('');

  const fileInputRef = useRef(null);
  const isMountedRef = useRef(true);

  useEffect(() => {
    const t = setTimeout(() => setSearchTerm(searchInput), 300);
    return () => clearTimeout(t);
  }, [searchInput]);

  useEffect(() => {
    isMountedRef.current = true;
    return () => { isMountedRef.current = false; };
  }, []);

  const fetchImages = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get('/admin/site-images');
      if (!isMountedRef.current) return;
      setImages(res.data?.images || []);
      setCategories(res.data?.categories || []);
    } catch {
      if (!isMountedRef.current) return;
      showToast?.('error', 'خطا در دریافت لیست عکس‌ها');
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    fetchImages();
  }, [fetchImages]);

  const filteredImages = useMemo(() => {
    return images.filter((img) => {
      const logicalCat = getLogicalCategory(img);
      const matchTab = activeTab === 'all' || logicalCat === activeTab;

      const q = searchTerm.trim().toLowerCase();
      const matchSearch = !q ||
        img.title.toLowerCase().includes(q) ||
        img.key.toLowerCase().includes(q) ||
        (img.description || '').toLowerCase().includes(q);

      return matchTab && matchSearch;
    });
  }, [images, activeTab, searchTerm]);

  const groupedImages = useMemo(() => {
    if (activeTab !== 'all') return null;
    const acc = {};
    filteredImages.forEach((img) => {
      const cat = getLogicalCategory(img);
      if (!acc[cat]) acc[cat] = [];
      acc[cat].push(img);
    });
    return acc;
  }, [filteredImages, activeTab]);

  // ============================================================
  //  Action Handlers
  // ============================================================
  const handleQuickUpload = async (image, file) => {
    const err = validateFile(file);
    if (err) return showToast?.('error', err);

    setSaving(true);
    try {
      const formData = new FormData();
      formData.append('title', image.title);
      formData.append('description', image.description || '');
      formData.append('category', image.category || 'other');
      formData.append('alt_text', image.alt_text || '');
      formData.append('is_active', String(image.is_active !== false));
      formData.append('object_fit', image.object_fit || DEFAULT_IMAGE_SETTINGS.object_fit);
      formData.append('zoom', String(image.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom));
      formData.append('pos_x', String(image.pos_x ?? DEFAULT_IMAGE_SETTINGS.pos_x));
      formData.append('pos_y', String(image.pos_y ?? DEFAULT_IMAGE_SETTINGS.pos_y));
      formData.append('file', file);

      await axios.put(`/admin/site-images/${image.id}`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (!isMountedRef.current) return;
      invalidateSiteImageCache(image.key);
      showToast?.('success', `عکس «${image.title}» آپلود شد`);
      fetchImages();
    } catch {
      showToast?.('error', 'خطا در آپلود عکس');
    } finally {
      setSaving(false);
    }
  };

  const openEditForm = (image) => {
    setEditingId(image.id);
    setForm({
      key: image.key,
      title: image.title,
      description: image.description || '',
      category: image.category || 'other',
      alt_text: image.alt_text || '',
      is_active: image.is_active !== false,
      object_fit: image.object_fit || DEFAULT_IMAGE_SETTINGS.object_fit,
      zoom: image.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
      pos_x: image.pos_x ?? DEFAULT_IMAGE_SETTINGS.pos_x,
      pos_y: image.pos_y ?? DEFAULT_IMAGE_SETTINGS.pos_y,
    });
    setFormFile(null);
    setFormFilePreview(image.url ? `${API_BASE}${image.url}` : null);
    setFormError('');
    setFormOpen(true);
  };

  const closeForm = () => {
    setFormOpen(false);
    setEditingId(null);
    setFormFile(null);
    setFormFilePreview(null);
    setFormError('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (!file) {
      setFormFile(null);
      setFormFilePreview(null);
      return;
    }
    const err = validateFile(file);
    if (err) return setFormError(err);

    setFormFile(file);
    setFormError('');
    const reader = new FileReader();
    reader.onloadend = () => {
      if (isMountedRef.current) setFormFilePreview(reader.result);
    };
    reader.readAsDataURL(file);
  };

  const handleFormChange = (e) => {
    const { name, value, type, checked } = e.target;
    if (['zoom', 'pos_x', 'pos_y'].includes(name) || type === 'range') {
      setForm((prev) => ({ ...prev, [name]: Number(value) }));
      return;
    }
    setForm((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
    setFormError('');
  };

  const handleSave = async () => {
    if (!form.title.trim()) return setFormError('عنوان الزامی است');

    setSaving(true);
    setFormError('');
    try {
      const formData = new FormData();
      formData.append('title', form.title);
      formData.append('description', form.description);
      formData.append('category', form.category);
      formData.append('alt_text', form.alt_text);
      formData.append('is_active', String(form.is_active));
      formData.append('object_fit', form.object_fit);
      formData.append('zoom', String(form.zoom));
      formData.append('pos_x', String(form.pos_x));
      formData.append('pos_y', String(form.pos_y));
      if (formFile) formData.append('file', formFile);

      await axios.put(`/admin/site-images/${editingId}`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (!isMountedRef.current) return;
      invalidateSiteImageCache(form.key);
      showToast?.('success', 'تنظیمات با موفقیت ذخیره شد');
      closeForm();
      fetchImages();
    } catch (err) {
      const detail = err?.response?.data?.detail;
      setFormError(typeof detail === 'string' ? detail : 'خطا در ذخیره');
    } finally {
      setSaving(false);
    }
  };

  const handleToggleActive = async (id) => {
    const target = images.find((img) => img.id === id);
    if (!target) return;

    setSaving(true);
    try {
      await axios.put(`/admin/site-images/${id}/toggle-active`);
      if (!isMountedRef.current) return;
      invalidateSiteImageCache(target.key);
      fetchImages();
      showToast?.('success', 'وضعیت تغییر یافت');
    } catch {
      showToast?.('error', 'خطا در تغییر وضعیت');
    } finally {
      setSaving(false);
    }
  };

  const handleCopyUsage = (image) => {
    const snippet = `<SiteImage imageKey="${image.key}" fallback="${image.fallback || '🐾'}" alt="${image.alt_text || image.title}" />`;
    navigator.clipboard?.writeText(snippet)
      .then(() => showToast?.('success', 'کد استفاده کپی شد'))
      .catch(() => showToast?.('error', 'کپی ناموفق بود'));
  };

  // ============================================================
  //  Render
  // ============================================================
  if (loading && images.length === 0) {
    return (
      <div className="p-12 text-center">
        <div className="inline-block w-8 h-8 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-4" />
        <div className="text-sm font-bold text-ink-500">در حال بارگذاری بانک تصاویر...</div>
      </div>
    );
  }

  return (
    <div className="space-y-4" dir="rtl">

      {/* ===== هدر فیکس‌شده (جستجو و تب‌ها) ===== */}
      <div className="bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl shadow-sm overflow-hidden sticky top-0 z-20">

        <div className="p-4 border-b border-ink-200 dark:border-dark-700 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h2 className="text-sm font-black text-ink-900 dark:text-cream-100 flex items-center gap-2">
              <span className="text-lg">🖼️</span> مدیریت تصاویر و آیکون‌ها
            </h2>
            <p className="text-[11px] text-ink-500 mt-1 font-bold">
              {toFa(images.length)} مورد ثبت شده در سیستم
            </p>
          </div>

          <div className="relative w-full md:w-72">
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="جستجو در عنوان یا کلید..."
              className="w-full pl-9 pr-3 py-2 border border-ink-200 dark:border-dark-600 rounded-xl text-xs bg-ink-50 dark:bg-ink-900 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none"
            />
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-ink-400">🔍</span>
          </div>
        </div>

        <div className="flex overflow-x-auto scrollbar-hide border-b border-ink-200 dark:border-dark-700 bg-ink-50/50 dark:bg-ink-900/30">
          {LOGICAL_TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex items-center gap-1.5 px-4 py-3 text-xs font-bold whitespace-nowrap transition-colors border-b-2 ${
                activeTab === tab.key
                  ? 'border-brand-500 text-brand-600 bg-white dark:bg-ink-800'
                  : 'border-transparent text-ink-500 hover:text-ink-800 hover:bg-ink-100 dark:hover:bg-ink-800'
              }`}
            >
              <span>{tab.icon}</span>
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* ===== گرید تصاویر ===== */}
      {filteredImages.length === 0 ? (
        <div className="bg-white dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl p-12 text-center shadow-sm">
          <div className="text-4xl mb-3 opacity-50">🔍</div>
          <div className="text-sm font-black text-ink-700 dark:text-cream-200">تصویری یافت نشد</div>
          <div className="text-xs text-ink-500 mt-1">عبارت جستجو یا دسته‌بندی دیگری را امتحان کنید.</div>
        </div>
      ) : (
        <div className="space-y-6">
          {activeTab === 'all' && groupedImages ? (
            Object.entries(groupedImages).map(([catKey, catImages]) => {
              const tabInfo = LOGICAL_TABS.find(t => t.key === catKey) || LOGICAL_TABS[LOGICAL_TABS.length - 1];
              return (
                <div key={catKey}>
                  <div className="flex items-center gap-2 mb-3 px-1">
                    <span className="text-lg">{tabInfo.icon}</span>
                    <h3 className="text-sm font-black text-ink-800 dark:text-cream-100">{tabInfo.label}</h3>
                    <span className="bg-ink-100 dark:bg-ink-700 text-ink-500 text-[10px] px-2 py-0.5 rounded-full font-bold">
                      {toFa(catImages.length)}
                    </span>
                    <div className="flex-1 h-px bg-ink-200 dark:bg-dark-700 mx-2" />
                  </div>
                  <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-3">
                    {catImages.map((image) => (
                      <ImageCard
                        key={image.id}
                        image={image}
                        onEdit={openEditForm}
                        onToggleActive={handleToggleActive}
                        onQuickUpload={handleQuickUpload}
                        onCopyUsage={handleCopyUsage}
                        saving={saving}
                      />
                    ))}
                  </div>
                </div>
              );
            })
          ) : (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-3">
              {filteredImages.map((image) => (
                <ImageCard
                  key={image.id}
                  image={image}
                  onEdit={openEditForm}
                  onToggleActive={handleToggleActive}
                  onQuickUpload={handleQuickUpload}
                  onCopyUsage={handleCopyUsage}
                  saving={saving}
                />
              ))}
            </div>
          )}
        </div>
      )}

      {/* ===== مودال تنظیمات پیشرفته ===== */}
      {formOpen && (
        <div className="fixed inset-0 bg-ink-900/70 backdrop-blur-sm flex items-end sm:items-center justify-center z-[60] p-0 sm:p-4">
          <div className="bg-white dark:bg-ink-800 rounded-t-2xl sm:rounded-2xl shadow-xl w-full sm:max-w-lg max-h-[92vh] overflow-hidden flex flex-col safe-bottom">

            <div className="p-4 border-b border-ink-200 dark:border-dark-700 flex items-center justify-between bg-ink-50 dark:bg-ink-900">
              <div className="font-black text-sm text-ink-900 dark:text-cream-100 flex items-center gap-2">
                <span>⚙️</span> تنظیمات پیشرفته: {form.title}
              </div>
              <button onClick={closeForm} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-ink-200 dark:hover:bg-ink-700">✕</button>
            </div>

            <div className="p-4 space-y-4 overflow-y-auto flex-1">

              <div className="bg-ink-50 dark:bg-ink-900 p-3 rounded-xl border border-ink-200 dark:border-dark-700">
                <div className="text-[10px] text-ink-500 mb-1">کلید سیستم (Key)</div>
                <div className="font-mono text-xs font-bold text-brand-600" dir="ltr">{form.key}</div>
              </div>

              <div>
                <label className="block text-xs font-bold mb-1">عنوان نمایشی</label>
                <input
                  type="text"
                  name="title"
                  value={form.title}
                  onChange={handleFormChange}
                  className="w-full border border-ink-200 dark:border-dark-600 rounded-lg p-2 text-sm bg-transparent focus:border-brand-500 outline-none"
                />
              </div>

              <div>
                <label className="block text-xs font-bold mb-1">دسته‌بندی دیتابیس (برای توسعه‌دهنده)</label>
                <select
                  name="category"
                  value={form.category}
                  onChange={handleFormChange}
                  className="w-full border border-ink-200 dark:border-dark-600 rounded-lg p-2 text-sm bg-transparent focus:border-brand-500 outline-none"
                >
                  {categories.map((cat) => (
                    <option key={cat} value={cat}>{CATEGORY_LABELS[cat] || cat}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold mb-1">تصویر جدید (اختیاری)</label>
                <div
                  className="border-2 border-dashed border-ink-200 dark:border-dark-600 rounded-xl p-4 text-center cursor-pointer hover:border-brand-400 transition"
                  onClick={() => fileInputRef.current?.click()}
                >
                  {formFilePreview ? (
                    <img src={formFilePreview} className="h-24 mx-auto object-contain rounded-lg" alt="Preview" />
                  ) : (
                    <div className="text-xs text-ink-500 py-4">برای انتخاب تصویر کلیک کنید</div>
                  )}
                </div>
                <input ref={fileInputRef} type="file" accept={ACCEPT_STRING} onChange={handleFileChange} className="hidden" />
              </div>

              <div className="space-y-3 p-3 rounded-xl border border-ink-200 dark:border-dark-700 bg-ink-50/50 dark:bg-ink-900/50">
                <div className="text-xs font-bold text-ink-800 dark:text-cream-200 mb-2">تنظیمات نمایش</div>

                <div>
                  <label className="block text-[11px] font-bold text-ink-500 mb-1">نحوه قرارگیری</label>
                  <select
                    name="object_fit"
                    value={form.object_fit}
                    onChange={handleFormChange}
                    className="w-full border border-ink-200 dark:border-dark-600 rounded-lg p-2 text-xs bg-white dark:bg-ink-800 outline-none"
                  >
                    {OBJECT_FIT_OPTIONS.map((opt) => (
                      <option key={opt.value} value={opt.value}>{opt.label}</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-3 pt-2">
                  <div>
                    <label className="flex justify-between text-[11px] font-bold mb-1">
                      <span>زوم</span>
                      <span className="text-brand-600">{toFa(form.zoom)}٪</span>
                    </label>
                    <input type="range" name="zoom" min="50" max="200" step="5" value={form.zoom} onChange={handleFormChange} className="w-full accent-brand-500" />
                  </div>
                  <div>
                    <label className="flex justify-between text-[11px] font-bold mb-1">
                      <span>موقعیت افقی</span>
                      <span className="text-brand-600">{toFa(form.pos_x)}٪</span>
                    </label>
                    <input type="range" name="pos_x" min="0" max="100" step="1" value={form.pos_x} onChange={handleFormChange} className="w-full accent-brand-500" />
                  </div>
                  <div className="col-span-2">
                    <label className="flex justify-between text-[11px] font-bold mb-1">
                      <span>موقعیت عمودی</span>
                      <span className="text-brand-600">{toFa(form.pos_y)}٪</span>
                    </label>
                    <input type="range" name="pos_y" min="0" max="100" step="1" value={form.pos_y} onChange={handleFormChange} className="w-full accent-brand-500" />
                  </div>
                </div>
              </div>

              <label className="flex items-center gap-2 p-3 rounded-xl border border-ink-200 dark:border-dark-600 cursor-pointer">
                <input type="checkbox" name="is_active" checked={form.is_active} onChange={handleFormChange} className="w-4 h-4 accent-brand-500 cursor-pointer" />
                <span className="text-xs font-bold text-ink-700 dark:text-cream-200">تصویر در سایت فعال باشد</span>
              </label>

              {formError && (
                <div className="text-xs font-bold text-rose-600 bg-rose-50 p-2 rounded-lg border border-rose-200">{formError}</div>
              )}
            </div>

            <div className="p-4 border-t border-ink-200 dark:border-dark-700 flex gap-2">
              <button onClick={closeForm} className="flex-1 py-2.5 rounded-xl text-sm font-bold border border-ink-200 dark:border-dark-600 hover:bg-ink-50 dark:hover:bg-ink-700">انصراف</button>
              <button onClick={handleSave} disabled={saving} className="flex-1 py-2.5 rounded-xl text-sm font-bold bg-brand-600 text-white hover:bg-brand-700 disabled:opacity-50">
                {saving ? 'در حال ذخیره...' : 'ذخیره تغییرات'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}