// frontend/src/utils/SiteImage.jsx
// ✅ v2 (Placeholder-Aware Loading + placeholderClassName):
//  - هوریستیک icon/image اصلاح شد (w-full/h-full دیگه icon حساب نمی‌شن)
//  - prop جدید placeholderClassName — امکان override پس‌زمینه placeholder
//  - در حالت loading، اگه placeholderContent داده بشه، همون نمایش داده می‌شه
//    (بدون پرش بصری، بدون ایموجی کوچیک)
// ============================================================
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_BASE } from '../config/api';

const CACHE_TTL = 5 * 60 * 1000; // 5 minutes (was 15 seconds)

const DEFAULT_IMAGE_SETTINGS = {
  objectFit: 'cover',
  zoom: 100,
  posX: 50,
  posY: 50,
};

const DEFAULT_PLACEHOLDER_CLASS = 'bg-paper-100 dark:bg-ink-700 text-ink-400';

const imageCache = new Map();
const pendingRequests = new Map();

// ============================================================
//  🔄 Version counter — برای force re-render کامپوننت‌ها
// ============================================================
let globalVersion = 0;
const versionListeners = new Set();

function bumpVersion() {
  globalVersion++;
  versionListeners.forEach((listener) => listener(globalVersion));
}

function useCacheVersion() {
  const [version, setVersion] = useState(globalVersion);
  useEffect(() => {
    versionListeners.add(setVersion);
    return () => versionListeners.delete(setVersion);
  }, []);
  return version;
}

// ============================================================
//  📡 BroadcastChannel — cross-tab sync
// ============================================================
const BROADCAST_CHANNEL_NAME = 'miko_site_images_updates';
let broadcastChannel = null;

if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
  try {
    broadcastChannel = new BroadcastChannel(BROADCAST_CHANNEL_NAME);
    broadcastChannel.onmessage = (event) => {
      if (event.data?.type === 'invalidate') {
        const key = event.data.key;
        if (key) imageCache.delete(key);
        else imageCache.clear();
        bumpVersion();
      }
    };
  } catch (err) {
    console.warn('BroadcastChannel init failed:', err);
  }
}

// ============================================================
//  👁️ Visibility/focus — invalidate وقتی کاربر برمی‌گرده
// ============================================================
if (typeof window !== 'undefined') {
  let lastInvalidation = 0;
  const MIN_INTERVAL = 1500;

  const handler = () => {
    if (document.visibilityState !== 'visible') return;
    const now = Date.now();
    if (now - lastInvalidation < MIN_INTERVAL) return;
    lastInvalidation = now;
    imageCache.clear();
    bumpVersion();
  };

  document.addEventListener('visibilitychange', handler);
  window.addEventListener('focus', handler);
}

// ============================================================
//  ⏰ Watchdog — TTL رو واقعاً اجرا کن
// ============================================================
if (typeof window !== 'undefined') {
  setInterval(() => {
    const now = Date.now();
    let changed = false;
    for (const [key, entry] of imageCache.entries()) {
      if (now - entry.timestamp > CACHE_TTL) {
        imageCache.delete(key);
        changed = true;
      }
    }
    if (changed) bumpVersion();
  }, 60000); // Check every 60s (was 3s)
}

// ============================================================
//  Cache helpers
// ============================================================
function getFromCache(key) {
  const entry = imageCache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > CACHE_TTL) {
    imageCache.delete(key);
    return null;
  }
  return entry;
}

function setInCache(key, raw) {
  if (!raw || (!raw.url && !raw.fallback)) return;
  const hasUrl = !!raw.url;
  const fullUrl = hasUrl
    ? (raw.url.startsWith('http') ? raw.url : `${API_BASE}${raw.url}`)
    : null;
  imageCache.set(key, {
    data: {
      url: raw.url || '',
      fallback: raw.fallback || '',
      objectFit: raw.object_fit ?? raw.objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit,
      zoom: raw.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
      posX: raw.pos_x ?? raw.posX ?? DEFAULT_IMAGE_SETTINGS.posX,
      posY: raw.pos_y ?? raw.posY ?? DEFAULT_IMAGE_SETTINGS.posY,
    },
    fullUrl,
    timestamp: Date.now(),
  });
}

function invalidateCache(key = null, broadcast = true) {
  if (key === null) imageCache.clear();
  else imageCache.delete(key);
  bumpVersion();

  if (broadcast && broadcastChannel) {
    try {
      broadcastChannel.postMessage({ type: 'invalidate', key });
    } catch {
      /* silent */
    }
  }
}

// ============================================================
//  Fetch
// ============================================================
async function fetchImageData(key) {
  const normalizedKey = (key || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/-/g, '_');

  if (!normalizedKey) return null;

  const cached = getFromCache(normalizedKey);
  if (cached) return cached;

  if (pendingRequests.has(normalizedKey)) return pendingRequests.get(normalizedKey);

  const promise = axios
    .get(`${API_BASE}/api/site-images/${normalizedKey}`)
    .then((res) => {
      const data = res.data;
      if (!data || (!data.url && !data.fallback)) return null;
      setInCache(normalizedKey, data);
      return getFromCache(normalizedKey);
    })
    .catch((err) => {
      if (err.response?.status === 404) return null;
      console.warn(`خطا در گرفتن عکس '${normalizedKey}':`, err);
      return null;
    })
    .finally(() => {
      pendingRequests.delete(normalizedKey);
    });

  pendingRequests.set(normalizedKey, promise);
  return promise;
}

function fetchImage(key) {
  return fetchImageData(key).then((entry) => entry?.fullUrl || null);
}

function isUrlLike(str) {
  if (!str) return false;
  return /^(https?:|\/|data:)/.test(String(str));
}

// ============================================================
//  Hook: useSiteImage
// ============================================================
export function useSiteImage(key) {
  const version = useCacheVersion();
  const [state, setState] = useState({
    url: null,
    fullUrl: null,
    fallback: '',
    ...DEFAULT_IMAGE_SETTINGS,
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (!key) {
      setState({ url: null, fullUrl: null, fallback: '', ...DEFAULT_IMAGE_SETTINGS, loading: false, error: null });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true }));

    fetchImageData(key)
      .then((entry) => {
        if (cancelled) return;
        if (!entry) {
          setState({ url: null, fullUrl: null, fallback: '', ...DEFAULT_IMAGE_SETTINGS, loading: false, error: null });
          return;
        }
        setState({
          url: entry.fullUrl,
          fullUrl: entry.fullUrl,
          fallback: entry.data.fallback || '',
          objectFit: entry.data.objectFit,
          zoom: entry.data.zoom,
          posX: entry.data.posX,
          posY: entry.data.posY,
          loading: false,
          error: null,
        });
      })
      .catch((err) => {
        if (cancelled) return;
        setState({ url: null, fullUrl: null, fallback: '', ...DEFAULT_IMAGE_SETTINGS, loading: false, error: err });
      });

    return () => {
      cancelled = true;
    };
  }, [key, version]);

  return state;
}

// ============================================================
//  Hook: useSiteImages (batch)
// ============================================================
export function useSiteImages(keys) {
  const version = useCacheVersion();
  const [state, setState] = useState({ images: {}, loading: true });

  useEffect(() => {
    if (!keys || !Array.isArray(keys) || keys.length === 0) {
      setState({ images: {}, loading: false });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true }));

    axios
      .get(`${API_BASE}/api/site-images/batch`, {
        params: { keys: keys.join(',') },
      })
      .then((res) => {
        if (cancelled) return;
        const imagesMap = res.data?.images || {};
        const processed = {};
        for (const [k, v] of Object.entries(imagesMap)) {
          if (v?.url) {
            const fullUrl = v.url.startsWith('http') ? v.url : `${API_BASE}${v.url}`;
            processed[k] = {
              url: fullUrl,
              fullUrl,
              objectFit: v.object_fit ?? v.objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit,
              zoom: v.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
              posX: v.pos_x ?? v.posX ?? DEFAULT_IMAGE_SETTINGS.posX,
              posY: v.pos_y ?? v.posY ?? DEFAULT_IMAGE_SETTINGS.posY,
            };
            setInCache(k, v);
          }
        }
        setState({ images: processed, loading: false });
      })
      .catch((err) => {
        if (cancelled) return;
        console.warn('خطا در گرفتن عکس‌ها (batch):', err);
        setState({ images: {}, loading: false });
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [keys?.join(','), version]);

  return state;
}

// ============================================================
//  Helper: تشخیص آیکون از روی className (fallback heuristic)
//  وقتی isIcon prop داده نشده باشه استفاده می‌شه.
//  ⚠️ w-full و h-full دیگه آیکون حساب نمی‌شن (باگ قبلی)
// ============================================================
function looksLikeIconClass(className) {
  if (!className) return false;
  if (className.includes('w-full') || className.includes('h-full')) return false;
  return (
    className.includes('text-') ||
    className.includes('w-') ||
    className.includes('h-')
  );
}

// ============================================================
//  کامپوننت SiteImage
// ============================================================
export function SiteImage({
  imageKey,
  fallback = null,
  alt = '',
  className = '',
  style = {},
  loadingClassName = '',
  showPlaceholder = false,
  placeholderContent = null,
  placeholderClassName = DEFAULT_PLACEHOLDER_CLASS, // ✅ NEW
  isIcon, // ✅ NEW: true → آیکون، false → تصویر، undefined → heuristic
  onError = null,
  objectFit: objectFitProp,
  zoom: zoomProp,
  posX: posXProp,
  posY: posYProp,
  useImageSettings = true,
  ...imgProps
}) {
  const { url, loading, fallback: dbFallback, objectFit, zoom, posX, posY } = useSiteImage(imageKey);
  const finalFallback = fallback ?? dbFallback ?? null;

  const computedStyle = (() => {
    if (!useImageSettings) return { ...style };

    const finalObjectFit = objectFitProp ?? objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit;
    const finalZoom = zoomProp ?? zoom ?? DEFAULT_IMAGE_SETTINGS.zoom;
    const finalPosX = posXProp ?? posX ?? DEFAULT_IMAGE_SETTINGS.posX;
    const finalPosY = posYProp ?? posY ?? DEFAULT_IMAGE_SETTINGS.posY;

    const dynamic = {
      objectFit: finalObjectFit,
      objectPosition: `${finalPosX}% ${finalPosY}%`,
    };

    if (finalZoom !== 100 && finalZoom > 0) {
      dynamic.transform = `scale(${finalZoom / 100})`;
      dynamic.transformOrigin = `${finalPosX}% ${finalPosY}%`;
    }

    return { ...dynamic, ...style };
  })();

  // ============================================================
  //  ✅ حالت loading
  // ============================================================
  if (loading) {
    const isIconMode = isIcon === true || (isIcon === undefined && looksLikeIconClass(className));

    if (isIconMode) {
      // آیکون: ایموجی fallback با opacity پایین تا layout نپره
      return (
        <span
          className={`${className} inline-flex items-center justify-center opacity-40 ${loadingClassName}`}
          style={style}
          aria-busy="true"
          aria-label="در حال بارگذاری آیکون..."
        >
          {finalFallback ? <span className="leading-none select-none">{finalFallback}</span> : null}
        </span>
      );
    }

    // ✅ FIX: تصویر — اگه placeholderContent هست، همونو نشون بده
    // (بدون پرش بصری، بدون ایموجی کوچیک ۱۶px)
    if (placeholderContent) {
      return (
        <div
          className={`flex items-center justify-center ${placeholderClassName} ${className} ${loadingClassName}`}
          style={style}
          aria-busy="true"
          aria-label={alt || 'در حال بارگذاری عکس...'}
        >
          {placeholderContent}
        </div>
      );
    }

    return (
      <div
        className={`bg-paper-100 dark:bg-ink-700 animate-pulse ${className} ${loadingClassName}`}
        style={style}
        aria-busy="true"
        aria-label="در حال بارگذاری عکس..."
      />
    );
  }

  // ============================================================
  //  ✅ حالت URL موجود
  // ============================================================
  if (url) {
    const hasExplicitSize = /\b(w-|h-|w-full|h-full)/.test(className);
    const sizeConstrainedClassName = `${className} max-w-full max-h-full`;
    const sizeConstrainedStyle = {
      maxWidth: '100%',
      maxHeight: '100%',
      ...(hasExplicitSize ? {} : { width: '1em', height: '1em' }),
      ...computedStyle,
    };
    return (
      <img
        src={url}
        alt={alt}
        className={sizeConstrainedClassName}
        style={sizeConstrainedStyle}
        loading="lazy"
        onError={(e) => {
          if (finalFallback && isUrlLike(finalFallback)) {
            e.target.src = finalFallback;
          } else {
            e.target.style.display = 'none';
          }
          onError?.(e);
        }}
        {...imgProps}
      />
    );
  }

  // ============================================================
  //  ✅ حالت placeholder (no URL, showPlaceholder=true)
  // ============================================================
  if (showPlaceholder) {
    return (
      <div
        className={`flex items-center justify-center ${placeholderClassName} ${className}`}
        style={style}
        aria-label={alt || 'عکس تنظیم نشده'}
      >
        {placeholderContent || <span className="text-2xl opacity-60" aria-hidden="true">🖼️</span>}
      </div>
    );
  }

  // ============================================================
  //  ✅ حالت fallback (no URL, showPlaceholder=false)
  // ============================================================
  if (finalFallback) {
    if (isUrlLike(finalFallback)) {
      const hasExplicitSize = /\b(w-|h-|w-full|h-full)/.test(className);
      return (
        <img
          src={finalFallback}
          alt={alt}
          className={`${className} max-w-full max-h-full`}
          style={{
            maxWidth: '100%',
            maxHeight: '100%',
            ...(hasExplicitSize ? {} : { width: '1em', height: '1em' }),
            ...style,
          }}
          loading="lazy"
          {...imgProps}
        />
      );
    }
    return (
      <div
        className={`flex items-center justify-center ${className}`}
        style={style}
        aria-label={alt || String(finalFallback)}
      >
        <span className="leading-none select-none">{finalFallback}</span>
      </div>
    );
  }

  return null;
}

// ============================================================
//  Helper exports
// ============================================================
export function prefetchSiteImage(key) {
  return fetchImage(key);
}

export function prefetchSiteImages(keys) {
  if (!Array.isArray(keys)) return Promise.resolve();
  return Promise.all(keys.map((k) => fetchImage(k)));
}

export function invalidateSiteImageCache(key = null) {
  invalidateCache(key, true);
}

export default SiteImage;